/* Bank expansion: original scenarios, stable IDs 181–400. */
(() => {
const bank=window.PMP_BANK,cases=window.PMP_CASES;
const domains={P:'People',R:'Process',B:'Business Environment'};
function add(d,task,approach,stem,options,explanation,extra={}){
 const item={id:bank.length+1,domain:domains[d],task,approach,stem,options,answer:[0],explanation,type:'single',...extra};
 if(!['match','hotspot'].includes(item.type)){const shift=(item.id*7)%options.length;item.options=options.slice(shift).concat(options.slice(0,shift));item.answer=item.answer.map(i=>(i-shift+options.length)%options.length).sort((a,b)=>a-b);}
 bank.push(item);
}
Object.assign(cases,{
 river:{title:'Case file 07 · Flood-warning service',text:'A regional authority is installing river gauges under a fixed civil-works plan and iterating a public warning application. The intended outcome is timely evacuation, including households without smartphones. A trial delivered 96% of app notifications within one minute, but only 58% of vulnerable households received an actionable warning. Emergency coordinators were absent from the trial design. A gauge supplier now reports a three-week delay. The authority has approved a temporary manual observation protocol for gaps in automated coverage.',facts:[['App delivery within 1 minute','96%'],['Vulnerable households reached','58%'],['Supplier delay','3 weeks'],['Manual fallback','Approved protocol available']]},
 museum:{title:'Case file 08 · Museum collection move',text:'A museum is relocating fragile collections before its old lease expires. The relocation plan is predictive, while the visitor catalogue is developed iteratively. A packaging test found humidity outside the approved range in two crates. Curators disagree with logistics staff about whether a faster route is acceptable. The contract permits substitute packaging only after conservation approval. The sponsor proposes moving the affected crates now because delaying the move could incur rent.',facts:[['Lease expiry','6 weeks away'],['Crates outside humidity tolerance','2'],['Packaging substitution','Conservation approval required'],['Move authorization for affected crates','Pending']]},
 payroll:{title:'Case file 09 · Payroll consolidation',text:'A company is consolidating payroll across three countries. Configuration is iterative; legal payroll rules and migration gates are controlled predictively. During rehearsal, 0.7% of employee records have unexplained net-pay differences. Finance will approve go-live only after every unexplained difference is resolved or formally dispositioned under the agreed criteria. Local payroll specialists fear losing their roles and have stopped attending mapping workshops. The vendor says that the aggregate payroll total reconciles.',facts:[['Unexplained individual differences','0.7% of records'],['Aggregate payroll total','Reconciles'],['Local specialist participation','Declining'],['Go-live authority','Finance gate']]},
 coldchain:{title:'Case file 10 · Vaccine distribution',text:'A distributor is piloting a new temperature-monitoring system on rural routes. Its success measure is a reduction in unusable shipments while maintaining timely delivery. Drivers report that alerts appear in a language they cannot read. The sensor dashboard shows 99% uptime, but a pilot shipment experienced an unexplained temperature excursion. A carrier offers a cheaper route with longer transfer time. The team has not validated the thermal performance of that route.',facts:[['Sensor dashboard uptime','99%'],['Driver alert comprehension','Low'],['Pilot temperature excursion','Unexplained'],['Proposed cheaper route','Not thermally validated']]},
 school:{title:'Case file 11 · School enrolment portal',text:'A district is delivering an enrolment portal in increments before the academic year. The goal is to reduce incomplete applications from 30% to 10%. The pilot achieved 12% among users who completed the online process, but excluded families who abandoned registration. School administrators request a document-upload feature; parents with limited connectivity prefer an assisted submission option. A sponsor wants to report that the target is nearly achieved. The product owner has authority to prioritize within the approved funding envelope.',facts:[['Baseline incomplete applications','30%'],['Target','10%'],['Pilot reported rate','12%, excluding abandonment'],['Prioritization authority','Product owner within funding limits']]},
 battery:{title:'Case file 12 · Battery recovery facility',text:'A company is building a battery recovery facility using a predictive construction plan and adaptive process-optimization trials. The business case depends on achieving an 85% recovery rate within six months of commissioning. A supplier proposes a lower-cost separation module with an unverified recovery rate. Community stakeholders request clearer information about noise and transport impacts. The procurement contract requires performance evidence before acceptance. A new transport restriction may affect inbound material volumes.',facts:[['Recovery target','85% within 6 months'],['Alternative module performance','Unverified'],['Community concerns','Noise and transport'],['External change','Possible inbound transport restriction']]}
});
// People — 72 additional items.
add('P',4,'Hybrid','In the flood-warning case, what should the project manager do first to address the coverage gap?', ['Bring emergency coordinators and representatives of underserved households into a review of warning channels and response needs.','Increase notification throughput using the current app-only design.','Ask the supplier to certify that all smartphones receive alerts.','Treat households without smartphones as outside the project’s responsibility.'],'The outcome is actionable warning and evacuation, not app throughput alone. Engage the missing stakeholders to understand channel and response barriers before optimizing a solution that excludes them.',{case:'river'});
add('P',2,'Hybrid','In the museum case, curators and logistics staff disagree about the faster route. What should the project manager facilitate?', ['A joint assessment against conservation limits, route conditions, timing, and authorized acceptance criteria.','A vote weighted by the number of staff in each department.','A decision by logistics because transport is its specialty.','A request for the sponsor to waive all conservation controls.'],'The disagreement contains legitimate preservation and schedule interests. Shared criteria and evidence support a workable decision; headcount and disciplinary ownership do not resolve the actual trade-off.',{case:'museum'});
add('P',4,'Hybrid','In the payroll case, how should the project manager respond to declining specialist participation?', ['Discuss the specialists’ concerns and work with organizational leaders on role clarity and meaningful involvement.','Replace local knowledge with the vendor’s standard mapping assumptions.','Escalate every absence as misconduct before discussing its cause.','Wait until go-live to explain the new operating model.'],'Fear about roles is affecting knowledge access and delivery. Understand and address the concern without promising employment outcomes beyond project authority. Ignoring local expertise could increase migration errors.',{case:'payroll'});
add('P',8,'Hybrid','In the vaccine-distribution case, which communication action should receive priority?', ['Work with drivers to provide understandable alerts and verify the required response through a practical exercise.','Send drivers the dashboard uptime report more frequently.','Rely on supervisors to translate every alert after a route finishes.','Reduce the number of alerts without examining their meaning.'],'An alert only supports action when its recipient understands it in time. Tailor language and verify comprehension; uptime and delayed translation cannot demonstrate effective incident communication.',{case:'coldchain'});
add('P',5,'Agile','In the enrolment-portal case, administrators and parents prefer different solutions. What should the project manager facilitate?', ['A discussion of the underlying completion barriers and trade-offs with the product owner and both groups.','A commitment to implement both requests in the next iteration regardless of capacity.','A decision based solely on the administrators’ organizational rank.','Separate promises to each group without changing the backlog.'],'Align on the user problem and decision criteria before choosing features. The product owner can prioritize within authority, informed by both perspectives. Incompatible promises do not resolve capacity or value trade-offs.',{case:'school'});
add('P',8,'Hybrid','In the battery-facility case, community representatives say technical reports do not explain how daily life will be affected. What should change?', ['Translate verified impacts into accessible information and agree a two-way feedback channel.','Send the same engineering reports at a higher frequency.','Limit communication to statutory notices even when questions remain unanswered.','Promise that construction will have no disruption before assessing impacts.'],'Useful communication connects reliable facts to the audience’s concerns. More technical detail may not answer practical questions. Trust requires honest limits and feedback, not unsupported assurances.',{case:'battery'});
add('P',1,'Predictive','A transport project’s charter emphasizes reliability, but the team is choosing low-cost components that increase maintenance downtime. What should the project manager clarify?', ['How selection decisions should support the agreed reliability outcome and lifecycle trade-offs.','That every purchase must use the lowest initial price.','That procurement decisions cannot influence project success.','That reliability will be considered only after handover.'],'Connect day-to-day decisions to the shared purpose. Purchase savings may be outweighed by lost service availability. A vision needs usable decision criteria throughout delivery.');
add('P',1,'Hybrid','A sponsor changes after a merger and asks the team to keep delivering without discussing strategic priorities. Two new business units expect different outcomes. What is the best first step?', ['Revalidate the shared vision and success measures with the new sponsor and affected business units.','Continue the old priorities until every original deliverable is finished.','Let each workstream choose its preferred new strategy.','Immediately discard all existing plans without reviewing their value.'],'A leadership change may alter assumptions, but does not automatically invalidate everything. Revalidate outcomes collaboratively before changing priorities or continuing blindly.');
add('P',1,'Agile','The team can describe every backlog item but cannot explain why the release matters. Which TWO actions best establish a common direction?', ['Agree an outcome-focused release goal with the product owner and stakeholders.','Use concrete customer examples to test shared understanding.','Replace the product goal with a list of individual utilization targets.','Keep the purpose within the sponsor group to avoid debate.','Treat completion of the existing backlog as the only possible goal.'],'A clear outcome and concrete examples connect work to purpose. Utilization and backlog completion describe activity, while hiding the rationale prevents shared ownership.',{type:'multi',answer:[0,1]});
add('P',1,'Predictive','A contractor interprets “minimum disruption” as no daytime work; the customer expects daytime work with protected access. What should happen before mobilization?', ['Resolve the interpretation through specific operating expectations and confirm the agreed understanding.','Ask both parties to sign the same ambiguous phrase again.','Allow the site crew to decide once work begins.','Assume the contractor’s interpretation controls because it plans the work.'],'The phrase hides incompatible assumptions. Make operational expectations explicit before committing resources. A signature or delegated guess does not clarify the underlying requirement.');
add('P',1,'Hybrid','A project team is split between improving speed and improving inclusion. The business case requires both, but does not state acceptable trade-offs. What should the project manager organize?', ['A facilitated discussion to define measurable outcomes and the authority for unavoidable trade-offs.','Two independent visions with no common decision process.','A competition between subteams to determine which objective survives.','A rule that whichever measure improves first becomes the only objective.'],'Competing dimensions of value need a shared decision framework. Keeping contradictory directions separate or choosing by happenstance leaves the team without guidance.');
add('P',1,'Agile','A product vision has not changed, but several new team members interpret it differently from experienced members. Which action is most appropriate?', ['Discuss representative user scenarios and ask members to explain how decisions support the vision.','Email the vision statement and assume the issue is solved.','Require new members to avoid making decisions for six months.','Ask the experienced members to make all future decisions privately.'],'Checking understanding through application reveals interpretation gaps. Repeating text or withholding responsibility does not build a common decision-making capability.');
add('P',1,'Predictive','During kickoff, stakeholders agree on deliverables but not on the business problem. What risk should the project manager address?', ['The team may deliver accepted outputs that do not satisfy the intended need.','The schedule cannot contain any milestones.','A signed charter becomes unnecessary when outputs are agreed.','All procurement must stop until benefits are fully realized.'],'Agreement on outputs does not necessarily mean agreement on the problem or outcome. Establish the connection early so delivery decisions can serve the intended purpose.');
add('P',1,'Hybrid','A sustainability commitment appears in the charter but is absent from team planning discussions. What is the best way to make it actionable?', ['Translate it into relevant decision criteria and success measures with the team and accountable stakeholders.','Add the word sustainability to each status report without changing decisions.','Delegate the entire commitment to marketing.','Treat the commitment as optional whenever schedule pressure rises.'],'A principle becomes operational through decisions, ownership, and measures. Repetition or delegation to publicity does not embed it in delivery; constraints cannot be silently waived.');
add('P',2,'Predictive','A subcontractor and the internal quality lead disagree about a test result. Both reference different versions of the acceptance specification. What should the project manager do first?', ['Confirm the controlled specification and reconcile the version mismatch with both parties.','Ask the sponsor to choose whichever result protects the deadline.','Repeat the test using both versions without resolving authority.','Treat the dispute solely as an interpersonal problem.'],'The immediate cause is inconsistent information, not necessarily unwillingness to cooperate. Establish the authoritative requirement before deciding whether retesting or corrective work is needed.');
add('P',2,'Agile','A team member objects to a decision after remaining silent in a planning meeting. The manager assumes agreement because nobody objected. What should the manager do?', ['Explore the concern and establish a clearer way to surface disagreement and confirm decisions.','Ignore the concern because silence permanently waives participation.','Require unanimous approval of every minor task forever.','Exclude the member from future planning meetings.'],'Silence can reflect uncertainty or barriers to speaking. Investigate the concern and improve decision confirmation without turning every decision into an impractical unanimity requirement.');
add('P',2,'Hybrid','A supplier and customer are blaming one another for integration defects. Which TWO facilitation actions are most useful?', ['Agree a shared defect-evidence set and investigate interface assumptions.','Establish respectful discussion rules and focus on jointly resolvable causes.','Publish an unverified blame ranking to pressure both parties.','Hide the defects until contractual negotiations are complete.','Let the loudest participant determine the cause.'],'Evidence and respectful joint problem solving help separate technical causes from defensive positions. Blame, concealment, and volume do not establish responsibility or a correction.',{type:'multi',answer:[0,1]});
add('P',2,'Predictive','A minor disagreement about a meeting room is interrupting an urgent safety briefing. Both parties agree to revisit it later. Which response is proportionate?', ['Temporarily defer the room dispute and complete the safety briefing, with a clear follow-up.','Treat deferral as the permanent solution to every conflict.','Cancel the safety briefing until the room issue is resolved.','Escalate both participants to disciplinary review immediately.'],'A time-limited deferral can be appropriate when a more urgent matter requires attention and follow-up is agreed. The context, rather than a universal preference for one conflict style, determines the response.');
add('P',2,'Agile','During a retrospective, two members present different recollections of a failed deployment. What should the facilitator do before recommending corrective action?', ['Review the timeline and records with the participants to establish a shared factual basis.','Select the account given by the more senior person.','Average their statements and treat the result as fact.','Skip the event because disagreement makes analysis impossible.'],'Reconstruct observable events before drawing conclusions. Seniority and compromise do not determine historical facts. A shared timeline can make disagreement useful rather than paralyzing.');
add('P',2,'Hybrid','A project lead wants immediate resolution of a conflict, but one participant has become too upset to discuss it constructively. What is the best response?', ['Arrange a brief cooling-off period and a specific time for a facilitated discussion.','Force an immediate public admission of fault.','Drop the issue permanently to avoid discomfort.','Send the participant’s emotional reaction to all stakeholders.'],'A short pause can restore productive dialogue when followed by a concrete resolution plan. Permanent avoidance leaves the issue active; coercion and public exposure can worsen it.');
add('P',2,'Predictive','Match each conflict situation to the most suitable immediate intervention. Use each intervention once.', ['Verify the authoritative facts','Control the immediate hazard','Facilitate shared trade-offs','Clarify responsibility'], 'Different causes require different first steps. Conflicting records need reconciliation, imminent hazards need protection, competing interests need facilitation, and an ownership gap needs explicit responsibility.',{type:'match',rows:['Two leads cite different approved drawings','Crews dispute a potentially dangerous lift already being prepared','Two stakeholders seek legitimate but competing service outcomes','No team accepts ownership of an interface task'],answer:[0,1,2,3]});
add('P',2,'Agile','A developer repeatedly bypasses peer review after the team explicitly agreed it was part of completion. No emergency exception applies. What should the project manager do?', ['Discuss the behavior and its cause, then reinforce and follow through on the agreed working rule.','Ignore it because the developer is highly productive.','Remove peer review from the agreement without team discussion.','Immediately require sponsor approval for every line of code.'],'Apply agreed rules consistently while investigating why they are bypassed. Exceptional productivity does not automatically waive quality commitments; excessive centralized control is not the first proportional response.');
add('P',3,'Agile','A team is capable of resolving a design issue but asks the manager for the answer because previous managers punished unsuccessful experiments. What should the manager establish?', ['Clear decision boundaries and a safe, accountable way to test and learn from bounded experiments.','A promise that no decision will ever have consequences.','A requirement that all design choices be escalated indefinitely.','A public criticism of the team’s dependence.'],'Empowerment requires both authority and a credible learning environment. Bounded experiments preserve accountability. Unlimited immunity and indefinite escalation are neither necessary nor useful.');
add('P',3,'Predictive','A replacement specialist is technically strong but unfamiliar with the organization’s safety procedures. What leadership approach is most appropriate initially?', ['Provide focused orientation and supervised application until the required competence is demonstrated.','Assume technical expertise proves local procedural competence.','Assign no meaningful work until project closure.','Allow the specialist to replace local procedures immediately.'],'Expertise in one area does not establish familiarity with local obligations. Tailor support to the actual gap and reduce supervision when readiness is demonstrated.');
add('P',3,'Hybrid','A team member consistently completes individual work but does not help resolve shared integration problems. The project depends on cross-team delivery. What feedback is most useful?', ['Discuss specific examples and agree expectations for contribution to shared outcomes.','Praise individual completion and ignore integrated delivery.','Assign the member every integration issue as punishment.','Compare personalities instead of discussing observable behavior.'],'Effective feedback links observable behavior to collective outcomes and future expectations. Punishment and personality judgments do not establish a constructive performance conversation.');
add('P',3,'Agile','A high-performing team proposes rotating facilitation of its daily coordination meeting. What should the project manager do?', ['Support the experiment while checking that coordination and inclusion remain effective.','Reject it because facilitation must always belong to the manager.','Require an organizational restructuring before trying it.','Stop attending any project discussions without explanation.'],'A capable team can experiment with how it coordinates within agreed boundaries. Support and observe the outcome without assuming either permanent managerial control or total disengagement is required.');
add('P',3,'Predictive','A temporary team contains several professional disciplines that use different terminology. Errors occur at handoffs. Which TWO actions best support team performance?', ['Develop shared definitions for critical handoff information.','Use cross-discipline walkthroughs to verify mutual understanding.','Require each discipline to maintain a private interpretation.','Remove specialists who ask clarifying questions.','Measure only the number of documents sent between teams.'],'Shared language and walkthroughs reduce misunderstandings at interfaces. Sending information is not evidence that it was understood, and discouraging clarification hides ambiguity.',{type:'multi',answer:[0,1]});
add('P',3,'Hybrid','A project manager learns that team members are working sustained overtime to conceal unrealistic commitments. What should happen next?', ['Review actual capacity, causes, and priorities with the team and negotiate a sustainable plan.','Praise the concealment because the dashboard remains green.','Require even more overtime before discussing scope.','Change recorded hours so utilization appears normal.'],'Transparent capacity planning protects sustainable delivery and credible forecasts. Concealing effort or normalizing chronic overload postpones the problem and distorts decisions.');
add('P',3,'Agile','The team’s retrospective produces criticism of the project manager’s slow decisions. What response best demonstrates accountable leadership?', ['Invite specific evidence, acknowledge relevant impacts, and agree an improvement with follow-up.','Explain that leadership decisions are outside the retrospective’s scope.','Ask team members to retract the criticism before discussing examples.','Delegate all future decisions without defining authority.'],'Accountable leadership includes receiving feedback and testing improvements. Defensiveness suppresses useful information; indiscriminate delegation may create a different governance gap.');
add('P',3,'Predictive','An inexperienced team is performing a novel high-risk task. Which leadership stance best fits the immediate context?', ['Provide clear direction, qualified support, and feedback, then adjust as capability increases.','Use complete hands-off delegation from the first day.','Make every future project decision personally regardless of capability.','Rely solely on motivational speeches.'],'Leadership should fit competence and risk. Initial direction can be appropriate without becoming permanent micromanagement. Motivation alone does not replace skill and safe execution controls.');
add('P',4,'Hybrid','A project’s most influential critic is also a key user of the planned service. What engagement approach is most useful?', ['Understand the critic’s concerns and involve them in evaluating relevant evidence and options.','Exclude the critic until the service is ready.','Send promotional material without inviting a response.','Assume influence makes the critic’s every request mandatory.'],'Influence and concern justify meaningful engagement, not exclusion or automatic compliance. Evidence-based involvement can uncover legitimate risks and improve the proposed solution.');
add('P',4,'Predictive','A new municipal department gains approval authority midway through a project. What should the project manager update first?', ['Stakeholder analysis and the related engagement and decision arrangements.','Only the project team’s vacation calendar.','The completed deliverables without discussing new requirements.','The original stakeholder register’s approval date only.'],'Changes in authority affect decision pathways and communication needs. Reassess the stakeholder and implications before making assumptions about required product changes.');
add('P',4,'Agile','A demonstration attracts enthusiastic feedback from managers but little input from the people who perform the daily workflow. Which TWO actions improve the evidence?', ['Invite representative frontline users to observe or try the increment.','Provide accessible ways for users to give candid feedback.','Treat manager enthusiasm as a complete substitute for user validation.','Remove negative comments from the review notes.','Require only written feedback in a format users cannot access.'],'Representative use and accessible feedback reduce the gap between managerial approval and operational usability. Selective or inaccessible feedback can create misleading confidence.',{type:'multi',answer:[0,1]});
add('P',4,'Hybrid','A stakeholder’s influence has fallen after an organizational change, but their team remains heavily affected by rollout. How should engagement change?', ['Reassess influence and needs while preserving meaningful involvement for affected users.','Remove the stakeholder solely because their title changed.','Use the original engagement plan without reviewing the change.','Give the stakeholder final approval authority to compensate.'],'Influence is one factor, not the sole reason to engage. Continued operational impact may justify substantial involvement even when formal authority changes.');
add('P',4,'Predictive','A local community group receives updates but says decisions are already final when it can comment. What should the project manager examine?', ['Whether engagement occurs early enough to influence decisions within the agreed boundaries.','Whether the updates use enough corporate branding.','Whether all feedback can be postponed until closure.','Whether information distribution alone proves meaningful participation.'],'Engagement requires a credible opportunity for relevant input, not just notification after decisions. Clarify where influence is possible and seek input before those choices close.');
add('P',4,'Agile','A product team consults only its most profitable customer while designing a shared platform. Other contracted users have different critical workflows. What should the project manager encourage?', ['A representative stakeholder analysis that includes the contractual and operational needs of other users.','Automatic adoption of every request from the most profitable customer.','An equal number of features for each customer regardless of value.','No customer consultation because their needs differ.'],'Commercial importance matters, but it does not erase other obligations or outcomes. Analyze the complete stakeholder context and make transparent trade-offs rather than using simplistic allocation rules.');
add('P',4,'Hybrid','Match the engagement gap to the best corrective action.', ['Include missing affected users','Clarify decision authority','Provide a feedback loop','Tailor information access'], 'First identify what prevents effective engagement. Missing representation, unclear authority, one-way reporting, and inaccessible information require distinct remedies.',{type:'match',rows:['Night-shift operators were never included in interviews','Two people each believe they alone can approve acceptance','Reports are sent, but questions have no response channel','Users cannot read the language used in rollout notices'],answer:[0,1,2,3]});
add('P',4,'Predictive','A stakeholder requests that sensitive commercial figures be shared with a wider audience to improve transparency. What should the project manager do?', ['Determine permitted disclosure and provide useful information at an appropriate level of detail.','Publish everything because transparency overrides all confidentiality commitments.','Stop all communication with the stakeholder.','Ask the stakeholder to forward restricted data informally.'],'Transparency and responsible information handling must coexist. Clarify access and tailor reporting without disclosing restricted material or using confidentiality as a reason for blanket silence.');
add('P',5,'Predictive','A sponsor expects immediate financial savings after launch, but the business case assumes a six-month adoption period. What should the project manager do?', ['Review the timing assumptions and align expectations using the approved benefit model and current evidence.','Promise immediate savings to maintain enthusiasm.','Delete the adoption period without changing the model.','Avoid the conversation until the first disappointing report.'],'Expectation alignment includes when benefits can reasonably occur. Discuss assumptions early rather than changing commitments informally or waiting for avoidable disappointment.');
add('P',5,'Agile','A stakeholder treats the release forecast as a guarantee of every listed feature. The team is using rolling planning. Which clarification is most important?', ['Explain forecast uncertainty, priorities, and the agreed basis for release decisions.','Say that agile forecasts have no meaning.','Convert every item into a fixed commitment without consulting the team.','Stop sharing future plans with stakeholders.'],'A forecast remains useful when its assumptions and confidence are understood. Adaptive planning does not mean no planning, nor does it justify unsupported fixed promises.');
add('P',5,'Hybrid','Two departments request different report definitions for the same indicator. What should the project manager facilitate?', ['Agreement on a common definition or clearly distinguished measures and their intended uses.','Two reports with the same label but undisclosed calculation differences.','Use of whichever definition produces the greener result.','Deletion of the indicator because stakeholders disagree.'],'Comparable reporting requires clear definitions. If purposes genuinely differ, distinguish the measures transparently rather than disguising incompatible calculations under one name.');
add('P',5,'Predictive','A customer asks for a “fully automated” handover, but some safety decisions legally require a qualified person. What should the project manager do?', ['Clarify the mandatory human decisions and agree a feasible interpretation of the automation objective.','Promise complete automation and resolve the constraint after acceptance.','Treat every manual step as evidence that the project must be cancelled.','Ask the team to omit the legal requirement from demonstrations.'],'Clarify the constraint and the achievable outcome. A broad aspiration cannot override mandatory decision requirements, but it may still support substantial useful automation.');
add('P',5,'Agile','Which TWO practices best prevent hidden expectation gaps during iterative delivery?', ['Discuss acceptance examples before implementation.','Review increments with stakeholders and act on feedback.','Treat the original request wording as permanently sufficient.','Use velocity as the only customer-satisfaction measure.','Avoid discussing limitations until final release.'],'Early examples and recurring feedback expose different interpretations while changes are still manageable. Output metrics and unchanged wording cannot replace shared understanding.',{type:'multi',answer:[0,1]});
add('P',5,'Hybrid','A vendor demonstration creates expectations for features outside the purchased configuration. What should the project manager do next?', ['Clarify the contracted configuration and discuss any desired additions through the appropriate decision process.','Allow the expectation to stand until deployment.','Demand all demonstrated features at no cost without reviewing the agreement.','Ask users to stop attending demonstrations.'],'Separate what was demonstrated from what is authorized and funded. Address the misunderstanding promptly and assess additions transparently rather than assuming entitlement or suppressing useful engagement.');
add('P',5,'Predictive','A junior stakeholder representative lacks confidence in negotiating service trade-offs with experienced managers. What support is most appropriate?', ['Offer mentoring and help the representative prepare evidence and clarify their authority.','Take over every discussion permanently.','Ask the representative to agree with senior managers by default.','Remove the group’s representation because it is inexperienced.'],'Mentoring strengthens participation while preserving representation and accountability. Permanent substitution or deference based on seniority leaves the capability and voice gap unresolved.');
add('P',5,'Agile','A customer says a feature is “essential,” but different users mean different things by the term. What should the team do before prioritizing?', ['Explore the underlying user outcomes and examples that make the feature important.','Assign maximum priority based only on the adjective.','Remove the feature because the request is ambiguous.','Ask developers to choose the business meaning without customer input.'],'Labels such as essential are starting points for inquiry. Understand the actual need and consequences before making a value or priority decision.');
add('P',6,'Hybrid','A service meets the agreed response-time target, yet users remain dissatisfied because requests are frequently reopened. What should the project manager investigate?', ['Whether the measures capture resolution quality and the actual customer experience.','Whether users can be persuaded to ignore reopened requests.','Whether faster first responses alone will prove success.','Whether satisfaction data should be removed from reporting.'],'A narrow metric can improve while the end-to-end experience deteriorates. Investigate what matters to customers instead of assuming the existing measure is complete.');
add('P',6,'Predictive','The customer’s acceptance lead changes shortly before handover and introduces unfamiliar expectations. What should the project manager do?', ['Review agreed acceptance criteria with the new lead and distinguish clarifications from proposed changes.','Reject every question from the new lead.','Accept every new expectation without impact analysis.','Ask the old lead to approve without confirming current authority.'],'Continuity requires shared understanding and valid authority. Use agreed criteria as the basis while evaluating legitimate changes through the appropriate process.');
add('P',6,'Agile','A customer requests reversing a recently accepted feature after actual usage reveals a problem. What should the team do?', ['Examine the usage evidence with the product owner and decide how to adapt the backlog.','Refuse all further discussion because acceptance is irrevocable evidence of value.','Reverse production behavior immediately without checking impacts.','Remove the customer from feedback activities.'],'Acceptance does not stop learning. Evaluate evidence and consequences before a controlled adaptation. Neither rigid refusal nor an unassessed reversal responsibly manages the outcome.');
add('P',6,'Hybrid','A pilot satisfaction survey excludes users who needed assistance. What should be corrected?', ['Include relevant assisted users and disclose the sample limitation when interpreting satisfaction.','Treat the excluded group as satisfied because they completed the process.','Report the result without noting the limitation.','Replace the survey with team utilization figures.'],'Sampling choices affect what conclusions are supported. Assisted users may have a different experience; include them or clearly bound the findings rather than treating absence as satisfaction.');
add('P',6,'Predictive','Which TWO pieces of evidence best support a claim that a handover meets customer expectations?', ['Results against jointly agreed acceptance criteria.','Feedback from representative users on the intended operational outcomes.','The number of hours the team worked.','A large volume of unsigned handover documents.','The fact that the original budget was consumed.'],'Acceptance evidence and representative outcome feedback speak directly to what customers need. Effort, document volume, and expenditure do not establish usefulness or acceptance.',{type:'multi',answer:[0,1]});
add('P',6,'Agile','The product owner accepts stories individually, but a user journey spanning several stories still fails. What is the best response?', ['Review end-to-end acceptance and integration with the product owner and users.','Assume individual acceptance proves the complete journey works.','Increase story counts without changing verification.','Ask users to adapt to the broken journey.'],'Local completion does not prove integrated usefulness. Evaluate the whole user outcome and identify the missing acceptance or integration coverage.');
add('P',6,'Hybrid','A service launches on time, but customers expected a support channel that was never agreed. What should the project manager do?', ['Clarify the expectation, assess its impact on outcomes, and agree an accountable response.','Ignore the concern because it is outside the delivered software.','Promise permanent free support without authority.','Declare success using schedule performance alone.'],'Customer expectations can affect realized value even when they involve an unplanned service component. Address the gap transparently without making unsupported commitments.');
add('P',6,'Predictive','A customer accepts a minor deviation with a documented concession from the authorized authority. How should the project manager communicate it?', ['Record the concession and its limits clearly in acceptance and handover information.','Report the deliverable as meeting every original requirement without qualification.','Treat the concession as permission for unrelated future deviations.','Keep the concession private from the operational owner.'],'An authorized concession has a specific scope. Preserve that context so acceptance and operations are accurate; it does not retroactively prove full conformance or grant a blanket exception.');
add('P',7,'Predictive','A migration team has documented commands but not the rationale for choosing rollback triggers. What should the project manager transfer before handover?', ['The decision context, trigger rationale, and practical application of the rollback criteria.','Only a copy of the command list.','The assumption that operators can infer all trade-offs later.','A rule prohibiting questions after the project closes.'],'Operational judgment depends on context as well as steps. Tacit rationale helps future owners apply a procedure when circumstances differ from the original rehearsal.');
add('P',7,'Agile','A team has no time reserved for cross-training and repeatedly postpones it. A single expert remains a delivery bottleneck. What should the project manager facilitate?', ['Make the dependency visible and plan bounded learning work alongside delivery priorities.','Wait for the expert to leave before prioritizing transfer.','Ask everyone to learn in unpaid personal time.','Record the risk but never adjust the work plan.'],'Knowledge transfer needs time and priority to reduce the dependency. Merely logging the risk or deferring until departure does not create capability.');
add('P',7,'Hybrid','Which TWO actions best verify that a receiving team can operate a new service?', ['Have the receiving team perform realistic operating and recovery tasks.','Review observed gaps against readiness criteria and close them with accountable owners.','Count attendance at the vendor’s presentation only.','Ask the delivery team to sign for operations without participation.','Store all support knowledge in a repository operations cannot access.'],'Demonstrated performance and gap resolution validate usable capability. Attendance and proxy signatures establish neither understanding nor readiness.',{type:'multi',answer:[0,1]});
add('P',7,'Predictive','A project used an unusual procurement strategy that worked only because a specific market condition existed. How should the lesson be recorded?', ['Describe the condition, decision rationale, outcome, and limits on future application.','Record that the strategy is always best.','Omit context so the lesson is shorter.','Store only the final contract value.'],'Transferable learning includes the conditions under which it applies. A context-free success claim can lead another project to choose an unsuitable strategy.');
add('P',7,'Agile','A distributed team learns mainly through informal conversations in one office. Remote members miss important design decisions. What should change?', ['Capture decision rationale accessibly and create deliberate opportunities for cross-location learning.','Require remote members to reconstruct conversations from code changes.','Stop all informal conversation.','Keep the knowledge local to avoid additional documentation.'],'Informal exchange is useful but can exclude others. Preserve its value while making important knowledge accessible and creating inclusive learning opportunities.');
add('P',7,'Hybrid','Match each knowledge-transfer weakness to a suitable remedy.', ['Hands-on demonstration by the receiver','Accessible shared repository','Capture rationale and assumptions','Planned pairing with a backup'], 'Transfer succeeds when knowledge can be found, understood, and applied by the receiving people. Each remedy addresses a different failure mode rather than increasing document volume indiscriminately.',{type:'match',rows:['Training attendance is recorded, but operational ability is unknown','Useful lessons exist only in a private folder','A procedure lists steps but omits why exceptions are handled differently','One specialist remains the only person able to execute a critical task'],answer:[0,1,2,3]});
add('P',7,'Predictive','A contractor’s engagement ends Friday, but the buyer has not received configuration details needed for support. What should the project manager prioritize?', ['Confirm contractual handover obligations and obtain verified transfer to the designated support owner.','Assume the contractor will answer questions indefinitely after departure.','Close procurement because the main deliverable is installed.','Ask the support team to rediscover the configuration without checking available records.'],'Installation does not complete all knowledge-transfer obligations. Use the agreed handover process while the expertise remains available and verify that the receiver has usable information.');
add('P',7,'Agile','Two teams maintain different solutions to the same recurring technical problem. Which approach best encourages learning without imposing a premature standard?', ['Compare contexts and results in a shared learning session and test whether practices can be reused.','Mandate the first solution without examining its assumptions.','Ban discussion to preserve team independence.','Merge the solutions without testing compatibility.'],'Shared inquiry can reveal reusable practices and legitimate contextual differences. Autonomy does not require isolation, and standardization should follow evidence rather than chronology.');
add('P',8,'Predictive','A report contains accurate percentages but omits that the remaining work includes the highest-risk integration. What should the project manager add?', ['Context on remaining risk, forecast implications, and decisions required.','More decimal places in the completion percentage only.','A green status based solely on the quantity completed.','A statement that unfinished work cannot be analyzed.'],'Stakeholders need decision-relevant context, not just numerical precision. A large completed fraction can coexist with substantial remaining uncertainty.');
add('P',8,'Hybrid','A sponsor asks for immediate notification of any issue threatening launch, while the plan currently provides only weekly reports. What should the project manager do?', ['Agree clear escalation triggers and channels and update the communication arrangements.','Send every task update immediately regardless of impact.','Wait for the next report even when a trigger-level issue occurs.','Treat the sponsor’s request as permission to bypass all governance.'],'Tailor timing to decision urgency using explicit triggers. More communication is not automatically better; the goal is timely, usable information within agreed accountability.');
add('P',8,'Agile','A daily coordination meeting has become a detailed status presentation to the manager. Members do not discuss dependencies. What should the facilitator emphasize?', ['Team coordination around the goal, impediments, and needed collaboration.','Longer individual presentations to improve managerial visibility.','A prohibition on discussing blocked work.','Replacing all team communication with a monthly report.'],'The meeting should help the team coordinate its work. Management visibility can be provided without displacing the discussion of dependencies and impediments.');
add('P',8,'Predictive','Which TWO actions improve the reliability of an AI-assisted executive summary?', ['Check its claims against authoritative project records.','Have an accountable human review omissions, uncertainty, and decision implications.','Assume a polished writing style proves accuracy.','Remove the source records once the summary is drafted.','Use the model’s confidence statement as formal approval.'],'AI can assist drafting but does not establish factual completeness or authority. Source validation and accountable review address hallucinated, omitted, or misleading claims.',{type:'multi',answer:[0,1]});
add('P',8,'Hybrid','Stakeholders complain that they cannot identify which decisions in a report are still pending. What reporting change is most useful?', ['Distinguish pending requests from approved decisions, including owners and due dates.','Remove all historical decisions without retaining traceability.','Increase the length of the narrative without changing structure.','Ask each reader to infer status from meeting attendance.'],'Explicit decision status, ownership, and timing make governance information usable. More prose is not a substitute for clear actionable distinctions.');
add('P',8,'Agile','A customer uses a screen reader and cannot interpret a dashboard supplied only as a screenshot. What should the team provide?', ['An accessible representation of the same key information and a way to confirm understanding.','A higher-resolution screenshot as the only response.','A requirement that the customer find someone else to read it.','No report because the existing format is standard.'],'Communication effectiveness includes accessibility. Equivalent usable information preserves participation; image resolution alone may not address the access barrier.');
add('P',8,'Predictive','A project’s official report is distributed on time, but decision makers repeatedly act on an older version forwarded by email. What should the project manager improve?', ['Version identification, access to the authoritative report, and communication of material updates.','Create more uncontrolled copies for convenience.','Delete the current report to avoid disagreement.','Stop recording changes between versions.'],'Clear version control and authoritative access reduce inconsistent decisions. Extra copies without controls can amplify the problem; losing change history harms traceability.');
add('P',8,'Hybrid','A steering committee wants to know whether a schedule recovery action worked. Which update is most informative?', ['The expected effect, observed results, remaining uncertainty, and any further decision needed.','Only the date the action was assigned.','Only the number of meetings held to discuss the action.','A success label based on the owner’s optimism.'],'Report the intervention’s effect against its intended outcome. Assignment and activity are not evidence of effectiveness, and remaining uncertainty should stay visible.');
add('P',4,'Predictive','A permitting authority has high power over the project but wants little routine detail unless an agreed threshold is crossed. Select the usual power–interest matrix starting point for its engagement.', ['Monitor','Keep informed','Keep satisfied','Manage closely'],'High power with low routine interest generally calls for keeping the stakeholder satisfied through targeted assurance and agreed escalation. The matrix is a starting point; actual needs and obligations still determine the plan.',{type:'hotspot',graphic:'stakeholders',answer:[2]});
add('P',4,'Hybrid','A group of frequent service users has low formal decision power but high interest in the new workflow. Select the usual power–interest matrix starting point for engagement.', ['Monitor','Keep informed','Keep satisfied','Manage closely'],'Low formal power with high interest generally suggests keeping users informed and inviting relevant feedback. Low power is not a reason to exclude affected people from meaningful participation.',{type:'hotspot',graphic:'stakeholders',answer:[1]});
// Process — 90 additional items.
add('R',1,'Hybrid','In the flood-warning case, the gauge delay creates a coverage gap. Which planning response is best supported by the facts?', ['Assess dependencies and activate the authorized manual fallback where appropriate while updating the integrated forecast.','Assume fast app notifications compensate for missing river observations.','Cancel all warning activities until every gauge arrives.','Treat the supplier’s delay as unrelated to the service outcome.'],'Planning should integrate the physical input, software, and operating response. An approved fallback may preserve coverage, but its feasibility and impacts still need assessment and coordination.',{case:'river'});
add('R',7,'Hybrid','In the museum case, humidity testing fails for two crates. What should the team do before moving those crates?', ['Contain the nonconformance, investigate it, and obtain the required conservation approval for the accepted solution.','Move them because only two crates failed.','Use substitute packaging without approval if it is cheaper.','Report only the average humidity across all crates.'],'A small number of failures can still threaten fragile collections. Follow the defined quality and approval process; averages cannot establish that each affected crate is acceptable.',{case:'museum'});
add('R',9,'Hybrid','In the payroll case, the aggregate total reconciles but individual net-pay differences remain. What is the most accurate status conclusion?', ['Aggregate reconciliation does not demonstrate that individual records meet the go-live criteria.','The zero aggregate difference proves every employee will be paid correctly.','Individual differences can be discarded because they cancel out.','The vendor’s confidence replaces the finance gate.'],'Compensating errors can hide beneath an aggregate total. Evaluate the specific acceptance criterion and disclose unresolved records rather than inferring record-level accuracy from a summary.',{case:'payroll'});
add('R',3,'Hybrid','In the vaccine-distribution case, which measure most directly tests the intended project benefit?', ['The rate of unusable shipments, considered alongside timely delivery.','Sensor uptime by itself.','The number of dashboard logins.','The number of alerts generated regardless of response.'],'The intended outcome concerns usable, timely shipments. Uptime and alert counts can support diagnosis but are intermediate measures, not proof that the benefit was achieved.',{case:'coldchain'});
add('R',9,'Agile','In the enrolment-portal case, why is the reported 12% incomplete-application rate insufficient to claim the target is nearly achieved?', ['It excludes abandonment and may not represent the full population covered by the outcome.','A pilot can never supply useful outcome evidence.','Any result above 10% proves the entire project has no value.','The rate should be replaced by developer velocity.'],'The measure omits an important failure path. Include or account for abandoned applications before comparing with a baseline defined for the whole process; useful pilot evidence still needs a valid denominator.',{case:'school'});
add('R',5,'Hybrid','In the battery-facility case, what should guide the decision on the cheaper module?', ['Performance evidence against contractual requirements and lifecycle value, evaluated through authorized procurement and change controls.','Purchase price alone because operating benefits occur after construction.','The supplier’s verbal assurance without supporting evidence.','Acceptance now with no documented performance obligation.'],'The module affects both a contractual acceptance condition and the business benefit. A lower price is not sufficient evidence of value or conformance.',{case:'battery'});
add('R',1,'Predictive','An integrated plan assumes a permit will be issued before construction, but the permit team’s latest forecast is later than mobilization. What should be done first?', ['Reconcile the dependency and analyze feasible sequencing and milestone impacts.','Keep the construction forecast unchanged until the permit is formally late.','Remove the permit task from the integrated plan.','Ask the contractor to start regulated work without authorization.'],'A credible plan must reflect the current dependency forecast. Reconcile assumptions early and evaluate authorized alternatives rather than waiting for a predictable issue.');
add('R',1,'Agile','A team is planning a product with uncertain usability but a stable integration API. What planning approach best uses those conditions?', ['Keep integration assumptions explicit and obtain frequent user feedback through small usable increments.','Freeze all user-interface requirements before any feedback is possible.','Treat the stable API as a reason to avoid user research.','Replace the API every iteration simply because the work is agile.'],'Tailoring distinguishes stable constraints from uncertain needs. Iterative feedback can reduce usability uncertainty without unnecessarily destabilizing an established interface.');
add('R',1,'Hybrid','Which TWO inputs are especially useful when selecting a development approach?', ['The stability of requirements and the cost of late changes.','The need for incremental feedback and external approval constraints.','The project manager’s preferred terminology alone.','The number of fashionable tools available.','An assumption that every workstream has identical uncertainty.'],'Select an approach from the work’s actual uncertainty, feedback needs, and constraints. Preferences and labels do not establish suitability, and different workstreams may need different treatment.',{type:'multi',answer:[0,1]});
add('R',1,'Predictive','A cost estimate was built from historical data for a much smaller project. Which action improves its usefulness?', ['Adjust for relevant differences and document assumptions, uncertainty, and the basis of estimate.','Multiply by an arbitrary factor and present an exact commitment.','Use the historical total unchanged because it is actual data.','Discard all historical evidence because the projects are not identical.'],'Historical information is useful when its applicability is assessed. Scale, context, and assumptions matter; neither blind reuse nor automatic rejection makes good use of evidence.');
add('R',1,'Hybrid','A plan includes each workstream’s output but no combined readiness milestone. What is the most important improvement?', ['Define integrated readiness criteria, dependencies, and shared review points.','Add more individual completion percentages only.','Assume all green workstreams guarantee a green release.','Remove cross-workstream dependencies to simplify reporting.'],'Integrated readiness may depend on interactions that local completion measures miss. Make the combined outcome and its dependencies explicit rather than equating local progress with system readiness.');
add('R',1,'Agile','A team learns that a proposed architecture cannot support a critical user requirement. The release plan still assumes that architecture. What should happen next?', ['Assess options with the relevant stakeholders and revise the plan based on the new evidence.','Continue unchanged because revising a plan signals failure.','Change every requirement without consulting the product owner.','Hide the discovery until the next funding cycle.'],'Plans should respond to validated learning. Evaluate feasible alternatives and their value, rather than treating the plan as immutable or changing requirements without accountability.');
add('R',1,'Predictive','A project manager proposes detailed planning for a work package that will not be defined for another year. What technique is most suitable?', ['Rolling-wave planning, with near-term detail and later work refined as information becomes available.','Inventing detailed tasks to eliminate every planning placeholder.','Avoiding any estimate of the later work.','Freezing uncertain assumptions permanently.'],'Rolling-wave planning matches detail to available knowledge while preserving a broader plan. False detail and no planning at all are not the only choices.',{type:'dropdown'});
add('R',1,'Hybrid','Match the planning condition to the most suitable emphasis.', ['Iterative discovery','Controlled baseline planning','Integrated hybrid coordination','Early uncertainty reduction'], 'Planning should fit the actual situation. Uncertain needs benefit from feedback, stable constrained work needs controlled commitments, mixed lifecycles need integration, and a critical unknown warrants targeted learning.',{type:'match',rows:['User behavior is unclear and prototypes can be tested cheaply','A fixed facility design requires staged statutory approvals','Hardware certification and evolving software share a release','A critical supplier interface has never been demonstrated'],answer:[0,1,2,3]});
add('R',2,'Predictive','A work package is described as “complete installation,” but team members disagree about whether commissioning is included. What should the project manager clarify?', ['Work-package boundaries, deliverables, and acceptance information in the scope documentation.','Only the work package’s budget code.','The team’s preferred interpretation after work finishes.','The schedule date as a substitute for defining the work.'],'Clear scope boundaries prevent omissions and duplicate assumptions. Dates and cost codes do not establish whether commissioning is part of the required deliverable.');
add('R',2,'Agile','A large backlog item combines account creation, billing, and reporting. Each capability can provide independent value. What should the team consider?', ['Split it into coherent, testable user-value slices.','Divide it only into analysis, coding, and testing phases.','Remove all acceptance examples to reduce its apparent size.','Keep it indivisible because it was requested in one sentence.'],'Independent valuable slices support prioritization and feedback. Phase-only splitting may produce no usable outcome, while deleting criteria hides rather than reduces complexity.');
add('R',2,'Predictive','Which TWO controls best reduce the risk of delivering an unrequested substitute for an agreed requirement?', ['Trace requirements to deliverables and verification evidence.','Review proposed scope changes with the authorized decision process.','Let individual developers replace difficult requirements without discussion.','Treat stakeholder silence as approval of every substitution.','Measure only the number of tasks completed.'],'Traceability and controlled decisions preserve alignment between agreed need and delivered result. Local convenience and output volume do not establish authorized scope.',{type:'multi',answer:[0,1]});
add('R',2,'Hybrid','A user story meets its written acceptance criteria, but a linked contractual requirement was omitted from those criteria. What should happen?', ['Assess and correct the coverage gap through the appropriate scope and quality controls.','Assume story acceptance automatically overrides the contract.','Delete the contractual requirement from traceability.','Treat the omission as proof that no additional work is needed.'],'Local criteria do not silently replace higher-level obligations. Investigate the omission and align the work and verification with the actual governing requirements.');
add('R',2,'Agile','A stakeholder requests a technical solution but cannot explain the problem it should solve. What should the team do before implementing it?', ['Clarify the intended outcome and constraints, then evaluate suitable solution options.','Build the named solution immediately to avoid questioning the stakeholder.','Reject the request because stakeholders cannot design systems.','Estimate only the coding effort and ignore the underlying need.'],'Understanding the problem supports value-based scope decisions. Respectful inquiry is not rejection; a prescribed solution may or may not be the best way to meet the need.');
add('R',2,'Predictive','A deliverable was informally accepted by a user who lacks delegated acceptance authority. What remains necessary?', ['Obtain acceptance from the authorized party using the agreed process and evidence.','Treat any positive comment as formal approval.','Repeat all work automatically without assessing the evidence.','Change the authority matrix retroactively without agreement.'],'Acceptance depends on both evidence and valid authority. Informal feedback is valuable but cannot substitute for the designated decision process.');
add('R',2,'Hybrid','Match each scope-related artifact to its main use in the situation.', ['Requirements traceability','Acceptance criteria','Work breakdown structure','Change record'], 'These artifacts answer different questions: coverage, completion conditions, decomposition, and the status of a proposed or approved alteration. None is a universal replacement for the others.',{type:'match',rows:['Check whether every agreed need has a test','Define observable conditions for accepting a deliverable','Organize the total deliverable scope into manageable packages','Track authorization and impact of a proposed scope adjustment'],answer:[0,1,2,3]});
add('R',2,'Predictive','An internal team discovers that a deliverable contains extra functionality the customer did not authorize. The additional feature increases maintenance effort. What is the best response?', ['Assess the impact and reconcile the deliverable with agreed scope through authorized decisions.','Assume all extra functionality is beneficial gold plating.','Conceal it until the customer begins maintenance.','Require the customer to accept the extra support obligation.'],'Extra work can reduce value and impose obligations. Evaluate its effect and authority rather than assuming more functionality always improves the outcome.');
add('R',3,'Agile','Two features have similar delivery effort. One removes a frequent obstacle for many users; the other serves an occasional preference of a single influential user. What should guide selection?', ['Evidence of expected outcomes, strategic fit, and constraints, reviewed with the product owner.','Influence alone, regardless of the product goal.','Alphabetical order of feature names.','A permanent rule that a majority need always overrides every other obligation.'],'Use evidence and context to compare value. Broad impact is relevant but must be considered alongside strategy and obligations, rather than replaced by influence or an absolute shortcut.');
add('R',3,'Predictive','A benefit depends on a separate operations initiative that has been cancelled. What should the project manager do?', ['Reassess the benefit assumptions and business case with the accountable owners.','Continue claiming the original benefit without qualification.','Treat the cancelled dependency as irrelevant because it is outside project scope.','Cancel the project unilaterally without review.'],'Value dependencies can cross project boundaries. Reassess the expected outcome and options with governance rather than ignoring the change or exceeding decision authority.');
add('R',3,'Hybrid','Which TWO elements make a benefits plan usable after project closure?', ['Named benefit owners with agreed review dates.','Defined measures and baselines linked to the intended outcomes.','Only the delivery team’s final timesheets.','A statement that benefits will appear automatically.','An unassigned list of hoped-for improvements.'],'Benefits need both measurable definitions and ongoing accountability. Delivery completion and positive expectations alone do not establish who will track or support realization.',{type:'multi',answer:[0,1]});
add('R',3,'Agile','A team proposes releasing a feature early, but the partial workflow would require users to re-enter sensitive data into an uncontrolled spreadsheet. What should the project manager facilitate?', ['An assessment of whether the increment provides acceptable value within security and operational constraints.','Release automatically because smaller increments are always safer.','Reject every future incremental release because one proposal has a problem.','Ask users to accept all risk without qualified review.'],'Incremental delivery is valuable when the slice is usable and meets relevant constraints. Small size alone does not establish safe or worthwhile delivery.');
add('R',3,'Predictive','A project delivers a system that saves staff time, but the organization has no plan to redeploy that capacity. What should the project manager examine with the benefit owner?', ['How the released capacity will translate into the intended business outcome.','Whether the team can claim all saved hours as cash savings automatically.','Whether benefits measurement can stop at system acceptance.','Whether utilization reports should be hidden from operations.'],'A technical efficiency may require organizational action to produce the promised benefit. Clarify the realization mechanism rather than equating theoretical time saved with actual financial value.');
add('R',3,'Hybrid','The chart shows median refund lead time by stage. Which intervention should be investigated first if the goal is a material reduction in end-to-end time?', ['The approval queue, while preserving necessary controls.','The upload step simply because it occurs first.','The payment step because it has the shortest time.','All stages must receive identical resources regardless of delay.'],'The approval queue contributes most of the measured elapsed time. Investigate its causes and safe improvement options; equal allocation or optimizing an already short step may have little overall effect.',{graphic:'bars',chart:{title:'Refund workflow · median elapsed hours',unit:'h',labels:['Upload','Validation','Approval queue','Payment'],values:[2,6,48,4]}});
add('R',3,'Agile','A team reports that every planned feature shipped, but usage is low. Which question most directly advances a value review?', ['What prevents intended users from achieving the targeted outcome with the delivered capability?','How can the team increase its count of shipped features?','How can nonusers be excluded from the benefit measure?','How can the original plan be presented as proof of adoption?'],'Investigate the gap between output and use. Feature counts and selective measurement cannot establish that the intended outcome has been realized.');
add('R',3,'Predictive','A sponsor is considering a cheaper implementation with much higher operating cost. What comparison best supports the decision?', ['Lifecycle value and costs, including the effect on benefits and risks.','Only the project’s purchase cost.','Only the implementation duration.','Only whether the delivery team likes the technology.'],'A project choice can transfer cost and risk into operations. Evaluate the whole value proposition instead of optimizing the delivery budget in isolation.');
add('R',4,'Predictive','A resource plan assumes one engineer can supervise simultaneous work at two distant sites. What should the project manager do?', ['Validate actual capacity and location constraints and develop a feasible allocation.','Record full availability at both sites to preserve the baseline.','Assume travel takes no time because the engineer is senior.','Wait until the first missed supervision requirement occurs.'],'Capacity includes where and when work can be performed. A nominal allocation does not make simultaneous physical obligations feasible.');
add('R',4,'Agile','A team has several partially completed items waiting for the same specialist. What experiment is most likely to improve flow?', ['Limit new starts and help the specialist finish or transfer the constrained work.','Start more items to keep everyone individually busy.','Count started items as completed.','Increase the specialist’s utilization target above available capacity.'],'The constraint limits finished value. Collaborating to reduce the queue can improve flow, whereas more starts and impossible utilization targets may worsen delay.');
add('R',4,'Hybrid','Which TWO inputs should shape a realistic resource plan for a shared specialist?', ['Confirmed availability across projects and relevant calendars.','The specialist’s required skills and the timing of dependent work.','The sum of all project managers’ preferred allocations, even if it exceeds capacity.','An assumption that all absences can be recovered through overtime.','Only the specialist’s job title.'],'Feasible allocation requires both real capacity and task-specific capability. Titles, competing wishes, and unexamined overtime assumptions do not establish availability.',{type:'multi',answer:[0,1]});
add('R',4,'Predictive','The chart compares demand with a team’s weekly capacity of 40 hours. Which week first requires a resource or sequencing decision?', ['Week 2','Week 1','Week 3 only','Week 4 only'],'Week 2 requires 52 hours against 40 available and is the first overload. Review priorities, sequencing, and authorized capacity options; a later underload does not automatically make earlier work feasible.',{graphic:'bars',chart:{title:'Specialist demand · capacity 40 hours/week',unit:'h',labels:['Week 1','Week 2','Week 3','Week 4'],values:[32,52,44,28]}});
add('R',4,'Hybrid','A project needs a skill unavailable internally for the next month. The work is time-critical. What should the project manager assess?', ['Feasible acquisition, training, sequencing, and scope options with their impacts and authority requirements.','Assign the work to an unqualified person and assume they will learn immediately.','Report the role as filled because a budget line exists.','Ignore the skill gap until the activity starts.'],'Resource management distinguishes funded positions from actual capability. Evaluate practical options early rather than equating headcount with readiness.');
add('R',4,'Agile','The team estimates an iteration using its usual capacity, but a mandatory training event removes two days. What should change?', ['Adjust available capacity and collaborate on a feasible selection of work.','Leave the commitment unchanged and conceal the training time.','Increase story-point estimates to make the same work look smaller.','Treat mandatory training as proof that planning is useless.'],'Known availability changes belong in planning. Honest capacity adjustment is more useful than manipulating estimates or relying on hidden work.');
add('R',4,'Predictive','Match the resource issue to the most relevant planning response.', ['Confirm calendars and allocation','Develop or acquire capability','Resolve the shared bottleneck','Validate physical suitability'], 'Availability, competence, shared demand, and equipment fitness are different constraints. Diagnose the actual issue before choosing a resource response.',{type:'match',rows:['A named engineer is assigned full-time to another project','The team has never performed a required specialist procedure','Three teams need the only test rig on the same day','A substitute machine cannot meet the required lifting capacity'],answer:[0,1,2,3]});
add('R',4,'Hybrid','A functional manager withdraws a promised resource after priorities change. What should the project manager do first?', ['Assess the impact and negotiate a revised allocation or alternative with the responsible stakeholders.','Assume the old commitment remains available in practice.','Threaten the resource personally for following the new assignment.','Change the project finish date without analyzing options.'],'Resource commitments can change, requiring impact assessment and accountable negotiation. Personal blame and unexamined date changes do not resolve the capacity problem.');
add('R',5,'Predictive','A buyer wants competitive proposals but gives bidders different answers to the same clarification question. What should procurement correct?', ['Provide consistent relevant clarification through the defined fair communication process.','Keep the difference because it may produce more creative bids.','Privately help only the bidder preferred by the sponsor.','Select the first proposal before other bidders can ask questions.'],'Comparable and fair evaluation requires consistent relevant information. Unequal clarification can distort competition and undermine the defensibility of the award.');
add('R',5,'Hybrid','A supplier promises rapid delivery but has not demonstrated compatibility with a mandatory interface. What should evaluation include?', ['Evidence of interface capability and delivery risk against the agreed selection criteria.','Only the promised delivery date.','A presumption that all commercial products integrate automatically.','A waiver of the interface requirement by the sales representative.'],'A fast incompatible deliverable may create no usable value. Verify relevant capability rather than treating a promise or commercial availability as integration evidence.');
add('R',5,'Predictive','Which TWO items should be clear before accepting a supplier milestone?', ['The contractual acceptance criteria and required evidence.','The authority and process for confirming acceptance.','Only whether the supplier issued an invoice.','Only the supplier’s internal completion percentage.','Whether the milestone looks attractive in a presentation.'],'Acceptance requires a defined basis and valid authorization. Invoicing and internal progress statements are inputs, not substitutes for the contractual decision.',{type:'multi',answer:[0,1]});
add('R',5,'Predictive','A seller’s costs increase under a firm-fixed-price agreement for unchanged scope. What should the project manager do before responding to a price-increase request?', ['Review the contract terms and facts with procurement rather than assuming the buyer must pay.','Approve every overrun because the supplier incurred it.','Ignore every request without checking applicable clauses.','Direct the supplier to reduce mandatory quality without agreement.'],'Risk allocation and relief depend on the actual agreement and facts. Fixed-price context matters, but the project manager should apply the contract rather than either automatically paying or refusing to review.');
add('R',5,'Hybrid','A procurement plan considers only purchase price, although disposal and support costs are significant. What should be added?', ['Relevant lifecycle costs, risks, and sustainability requirements to the evaluation basis.','Only a larger number of bidders.','A rule that all operating costs belong outside every project decision.','A scoring adjustment made after bids are opened to favor a preferred vendor.'],'A fair evaluation should consider the costs and outcomes relevant to the purchase decision and disclose its basis appropriately. More bidders cannot fix an incomplete value model.');
add('R',5,'Predictive','A supplier delivers the specified quantity, but half the items lack required certificates. What is the best next action?', ['Follow the contractual verification and nonconformance process for the missing evidence.','Accept all items because the quantity is correct.','Destroy the items without checking the agreement.','Create certificates internally without verification.'],'Quantity is only one acceptance condition. Resolve the evidence gap through the agreement rather than inventing proof or taking disproportionate unilateral action.');
add('R',5,'Hybrid','Match each procurement need to a generally suitable consideration. Specific contract terms still govern.', ['Firm fixed price','Time and materials with a ceiling','Cost-reimbursable with controls','Performance-based acceptance'], 'Contract selection depends on scope clarity, uncertainty, and risk allocation. The examples illustrate considerations, not universal rules or substitutes for procurement advice.',{type:'match',rows:['Well-defined scope; seller is to bear agreed-scope cost-overrun risk','Short investigation; uncertain effort; buyer needs defined rates and a spending cap','Exploratory work with substantial uncertainty and verified allowable-cost controls','Buyer needs proof of an operational outcome before accepting the milestone'],answer:[0,1,2,3]});
add('R',5,'Predictive','A supplier asks a project team member to approve a variation informally to save time. The member lacks that authority. What should the project manager reinforce?', ['Use the authorized variation process and communicate the applicable decision rights.','Allow verbal approval whenever the amount seems small.','Let the supplier define the buyer’s approval thresholds.','Implement first and seek retrospective signatures as a routine practice.'],'Informality does not create authority. A proportionate, defined change route can enable timely decisions without bypassing the agreement.');
add('R',6,'Predictive','At the reporting date, EV is $180,000, AC is $225,000, and PV is $200,000. Which interpretation is supported?', ['$45,000 over budget for the work performed and behind the planned work volume.','$25,000 over budget and ahead of schedule.','$45,000 under budget and behind schedule.','The final completion date will be exactly 10% late.'],'CV = EV − AC = −$45,000; SPI = EV/PV = 0.90. These indicate unfavorable cost and schedule performance. SPI alone does not establish an exact final completion date.');
add('R',6,'Predictive','A project has BAC $600,000, EV $240,000, and AC $300,000. Current cost efficiency is expected to persist; schedule effects are not included. Select the forecast EAC.', ['$750,000','$660,000','$540,000','$900,000'],'CPI = 240,000/300,000 = 0.80. Under the stated continuing-efficiency assumption, EAC = BAC/CPI = $750,000. BAC + AC − EV assumes remaining work performs at the original budgeted rate.',{type:'dropdown'});
add('R',6,'Predictive','A completed prototype cost $20,000 more than planned because of a one-time test failure. The team supports the original estimates for all remaining work. What forecast best fits this assumption?', ['Actual cost to date plus the original budget for remaining work.','Original total budget divided by the current CPI regardless of cause.','Original total budget with the overrun excluded.','Actual cost to date with no allowance for unfinished work.'],'A nonrecurring variance supports EAC = AC + (BAC − EV), if the remaining estimates remain credible. Automatically projecting a temporary inefficiency across all future work contradicts the stated evidence.');
add('R',6,'Hybrid','A release is within its total funding limit, but a large supplier payment falls due before the next funding tranche. What needs attention?', ['Cash-flow timing and an authorized funding or payment arrangement.','Only the final cost variance.','Increasing reported earned value to cover the payment.','Removing the liability from the forecast until cash arrives.'],'Budget sufficiency and cash availability are different constraints. Address the timing with responsible finance and procurement stakeholders; accounting presentation cannot create funds.');
add('R',6,'Predictive','Which TWO facts are needed to judge whether the remaining budget is realistic after an overrun?', ['A credible estimate of remaining work and its assumptions.','The efficiency required to finish within the remaining funds.','The sponsor’s preference to retain the original number as proof of feasibility.','The amount already spent as the sole justification for continuation.','The number of completed status reports.'],'Compare a bottom-up remaining estimate and required future efficiency with credible delivery capability. A preferred target or sunk expenditure cannot establish whether the remaining work is affordable.',{type:'multi',answer:[0,1]});
add('R',6,'Predictive','BAC is $500,000, EV is $200,000, and AC is $250,000. What TCPI is required to meet BAC?', ['1.20','0.80','1.25','0.60'],'TCPI to BAC = (BAC − EV)/(BAC − AC) = 300,000/250,000 = 1.20. This is the required efficiency for remaining work, not the historical CPI of 0.80.',{type:'dropdown'});
add('R',6,'Agile','An agile team’s monthly cost is stable, but newly discovered mandatory work has increased the release forecast by two months. What should the project manager communicate?', ['The forecast cost impact, uncertainty, and scope or delivery options for an authorized decision.','That a fixed monthly burn rate guarantees a fixed total cost.','That cost forecasting cannot be used with adaptive delivery.','A lower burn rate obtained by excluding shared service charges.'],'Stable cost per month does not mean stable total expenditure when duration changes. Explain the remaining-work forecast and meaningful options using a complete, consistent cost basis.');
add('R',6,'Predictive','Match each earned-value measure to its interpretation.', ['Cost efficiency achieved','Schedule efficiency in budgeted work units','Forecast total expenditure','Required future cost efficiency'], 'CPI and SPI describe performance to date; EAC forecasts total cost; TCPI expresses the efficiency needed for a specified target. None alone guarantees an achievable completion plan.',{type:'match',rows:['CPI','SPI','EAC','TCPI'],answer:[0,1,2,3]});
add('R',7,'Predictive','A process is statistically stable but repeatedly produces dimensions outside the customer’s tolerance. What should the team investigate?', ['Whether the process is capable of meeting the specification.','Only whether any point exceeds a control limit.','Whether the customer will accept stability as a substitute for conformance.','Whether removing the worst measurements makes the chart stable.'],'Control limits describe process behavior; specification limits describe required results. A stable process can still be incapable. Improving capability is different from investigating special-cause variation.');
add('R',7,'Hybrid','A supplier inspection catches the same assembly defect every week. What action best reduces recurrence?', ['Analyze the production cause and verify the effectiveness of a corrective change.','Increase the inspection report frequency without changing the process.','Accept the defects because the inspection detects them.','Retrain every inspector before checking where the defect originates.'],'Detection protects acceptance but does not remove the production cause. Use evidence to select corrective action and check subsequent results rather than assuming inspection effort prevents recurrence.');
add('R',7,'Agile','A team marks stories complete before accessibility checks, leaving remediation to a later release. Which TWO responses improve quality integration?', ['Agree relevant accessibility checks within the definition of done.','Build the capability and capacity to perform those checks during delivery.','Rename unfinished accessibility work as optional technical debt.','Count untested stories as accepted to protect velocity.','Ask users to discover all accessibility defects after deployment.'],'Required quality belongs in completion criteria and the work needed to meet them. A stronger definition alone is insufficient without the means to execute it; relabeling work does not satisfy the requirement.',{type:'multi',answer:[0,1]});
add('R',7,'Predictive','The chart shows defect categories from a sample of 100 units. If effort is limited to one category, where should cause analysis start to address the most recorded defects?', ['Seal alignment','Label position','Surface finish','Packing count'],'Seal alignment has 42 defects, more than any other category in this sample. Frequency helps focus investigation, but the chart does not identify the root cause or replace consideration of severity.',{graphic:'bars',chart:{title:'Defects by category',unit:'defects',labels:['Seal alignment','Label position','Surface finish','Packing count'],values:[42,28,18,12]}});
add('R',7,'Predictive','An acceptance test fails. The team proposes repeatedly rerunning it until one execution passes, with no investigation. What is the best response?', ['Investigate the failure and apply the agreed retest and acceptance criteria.','Accept the first passing rerun and discard earlier results.','Average pass and fail results without checking the test procedure.','Change the acceptance threshold after seeing the result.'],'Selective reruns can hide intermittent defects or unreliable tests. Establish the cause and use an agreed, traceable acceptance process; a favorable isolated result is not sufficient evidence.');
add('R',7,'Hybrid','An audit finds that reviewers use different versions of a mandatory checklist. What should the project manager do?', ['Resolve document control and evaluate the impact on work already reviewed.','Publish a new checklist without checking previous approvals.','Assume all old reviews are invalid without examining differences.','Ask reviewers to choose whichever version is shorter.'],'Correct the control failure and assess consequences proportionately. Publishing a current version prevents some future errors but does not establish whether earlier decisions met the required criteria.');
add('R',7,'Agile','A product passes functional tests, but users make frequent mistakes during a realistic task trial. What should the team do next?', ['Investigate usability with representative users and prioritize changes against acceptance needs.','Close the issue because the software follows its internal specification.','Treat every user mistake as a training failure before observing the task.','Add more functions to distract from the difficult workflow.'],'Fitness for use includes whether intended users can accomplish the task reliably. Functional conformance alone does not explain the observed difficulty; investigate before prescribing training or new features.');
add('R',7,'Predictive','Match the quality activity to its primary purpose.', ['Prevent defects through process improvement','Check deliverable conformance','Confirm customer acceptance','Establish the cause of a recurring problem'], 'Process improvement, inspection, acceptance, and root-cause analysis serve distinct purposes. They complement one another; passing an internal inspection does not automatically constitute customer acceptance.',{type:'match',rows:['Redesign a mistake-prone assembly method','Measure a completed part against tolerance','Obtain an authorized sign-off against acceptance criteria','Trace repeated leaks to an incorrectly calibrated fixture'],answer:[0,1,2,3]});
add('R',8,'Predictive','Two paths have durations of 14 and 17 days. A noncritical activity on the 14-day path slips two days, with no resource effects. What is the revised project duration?', ['17 days','19 days','16 days','14 days'],'The shorter path becomes 16 days, still below the 17-day controlling path. The two-day delay consumes float but does not extend completion under the stated assumptions.',{type:'dropdown'});
add('R',8,'Predictive','A project must finish earlier. Which information is most useful before selecting activities to crash?', ['Critical-path membership, feasible reductions, incremental cost, and resulting risks.','Only the longest activity anywhere in the schedule.','Only the activity with the largest original budget.','The number of people who volunteer for overtime.'],'Crashing shortens completion only when it addresses controlling work and feasible reductions. Evaluate incremental cost and risk, then recalculate paths because the critical path can change.');
add('R',8,'Predictive','An activity has optimistic, most likely, and pessimistic estimates of 4, 7, and 16 days. Using the beta-weighted PERT formula, what is its expected duration?', ['8 days','9 days','7 days','10 days'],'The specified formula is (O + 4M + P)/6 = (4 + 28 + 16)/6 = 8 days. The unweighted three-point mean is 9 days and is a different estimation assumption.',{type:'dropdown'});
add('R',8,'Hybrid','A hardware delivery date changes. Several software tasks depend on access to that hardware. Which TWO actions should come before promising a revised release date?', ['Reassess affected dependencies and the controlling path.','Evaluate alternatives and their risks with responsible teams.','Add the supplier delay to every software activity.','Keep the original forecast confidentially while publishing an unsupported earlier date.','Remove dependency links to make the schedule fit.'],'The effect depends on logic, float, and viable alternatives such as validated test substitutes. Analyze the network and options before making a commitment; deleting links does not remove real dependencies.',{type:'multi',answer:[0,1]});
add('R',8,'Agile','A team’s throughput varies from four to eight similarly sized items per week. A stakeholder wants a delivery date for 40 items. What is most appropriate?', ['Provide a forecast range using historical throughput and explain assumptions and confidence.','Guarantee five weeks because eight items was once achieved.','Guarantee ten weeks without considering changes in item size or capacity.','Refuse to forecast until all items are complete.'],'Historical delivery data supports probabilistic or range-based forecasting. A best observed week is not a reliable guarantee; make scope, capacity, and data limitations visible and update the forecast.');
add('R',8,'Predictive','An activity may start only after a required permit is issued by a regulator. How should this dependency be represented?', ['As an external constraint or dependency with a monitored approval milestone.','As discretionary logic the team may remove to compress the plan.','As already satisfied because the application was submitted.','As a team resource estimate with no link to the activity.'],'The team cannot waive the external approval requirement. Model and monitor it explicitly so its uncertainty and effect on downstream work are visible; application and authorization are different events.');
add('R',8,'Predictive','Resource leveling resolves an overallocation but moves completion beyond the approved date. What should happen next?', ['Evaluate the trade-off and alternatives through the appropriate decision process.','Delete the leveling result because it conflicts with the baseline.','Treat the original date as feasible without restoring the missing capacity.','Automatically add unapproved resources to preserve the date.'],'The leveled schedule exposes a real resource constraint. Assess authorized options and impacts rather than concealing the conflict or assuming additional funding and capacity are available.');
add('R',8,'Predictive','Match the schedule technique to its defining characteristic.', ['Crashing','Fast tracking','Resource leveling','Rolling-wave planning'], 'These techniques address different needs: added resources, overlapping work, constrained allocation, and progressive detail. Each has trade-offs and should be selected based on the actual scheduling problem.',{type:'match',rows:['Pay for an additional qualified crew to shorten controlling work','Overlap activities previously planned sequentially where feasible','Resolve allocation above a resource’s available capacity','Detail near-term work while keeping distant work at a higher level'],answer:[0,1,2,3]});
add('R',9,'Hybrid','An executive dashboard is green, but its data is three weeks old and a critical dependency has since failed. What should the project manager do?', ['Update the assessment using current evidence and explain the material change and response.','Keep the green status until the scheduled monthly meeting.','Change the color without explaining why or validating other data.','Ask the dependency owner to withhold the failure until recovery.'],'A decision aid must represent current material facts and make its reporting period clear. Timely, evidence-based escalation supports action; stale or unexplained indicators mislead decision makers.');
add('R',9,'Agile','Velocity rises after the team doubles its point estimates, while completed customer outcomes remain unchanged. What conclusion is justified?', ['The measurement scale changed; the apparent increase does not establish improved delivery.','Productivity doubled because the chart shows twice as many points.','Business value doubled because points measure customer benefit.','The team can now commit to twice as much comparable work.'],'Story points depend on the team’s estimation scale. Changing that scale breaks direct comparison. Check consistent delivery and outcome measures before claiming a performance improvement.');
add('R',9,'Predictive','Which TWO practices make a status report more useful for a steering decision?', ['Separate confirmed facts, forecasts, and assumptions.','Identify decisions needed, responsible owners, and required dates.','Hide uncertainty to make the report more concise.','Include every raw log entry without prioritization.','Report activity counts as the sole measure of benefits.'],'Governance needs reliable context and a clear decision request. Explicit uncertainty and actionable ownership help; volume of detail or activity counts alone do not explain whether intervention is required.',{type:'multi',answer:[0,1]});
add('R',9,'Hybrid','A team keeps two conflicting versions of an approved interface specification. What is the best response?', ['Establish the authoritative version through configuration control and assess affected work.','Let each team select the version that best fits its implementation.','Merge the versions informally without checking approval history.','Delete both versions and rely on verbal recollection.'],'Configuration control establishes a traceable basis for work. Resolve authority and impacts rather than creating a third unapproved interpretation or losing the evidence needed to reconcile changes.');
add('R',9,'Agile','The chart shows completed items per week with unchanged sizing and capacity. Which statement is supported?', ['Throughput varied; the last week alone is insufficient to establish a sustained improvement.','Throughput increased every week.','The team must commit to 12 items in every future week.','All remaining work will finish in one week.'],'The sequence 8, 11, 7, 12 varies. A recent high value does not establish a trend or guarantee future performance; use a sufficient history and consider context when forecasting.',{graphic:'bars',chart:{title:'Weekly throughput',unit:'items',labels:['Week 1','Week 2','Week 3','Week 4'],values:[8,11,7,12]}});
add('R',9,'Predictive','A sponsor requests a report that omits an unfavorable forecast from the version sent to the board. What should the project manager do?', ['Provide an accurate material forecast through the authorized reporting and escalation channels.','Omit it because the sponsor owns all project information.','Replace the forecast with the original target without labeling it.','Circulate confidential details publicly to counter the sponsor.'],'Accountable reporting distinguishes a target from a forecast and includes material issues. Address pressure through appropriate governance; neither concealment nor indiscriminate disclosure is an acceptable response.');
add('R',9,'Hybrid','A decision log records outcomes but not the assumptions behind them. A key assumption has now changed. What should be improved?', ['Record decision rationale and assumptions so affected decisions can be reassessed.','Treat every recorded decision as permanent regardless of context.','Reopen all decisions without identifying which are affected.','Remove previous entries so the log contains only current opinions.'],'Traceable rationale makes reassessment targeted and defensible. Preserve history and identify the decisions affected by new evidence rather than treating all past decisions as fixed or irrelevant.');
add('R',9,'Predictive','Match the information to its most appropriate project record.', ['Issue log','Risk register','Decision log','Change log'], 'An issue has occurred, a risk is uncertain, a decision records an authorized choice, and a change log tracks proposed or processed changes. These records may cross-reference one another.',{type:'match',rows:['A test environment failed this morning and needs restoration','A future restriction may reduce supplier capacity','The steering committee selected option B with a stated rationale','A request to alter the approved scope is awaiting disposition'],answer:[0,1,2,3]});
add('R',10,'Predictive','A sponsor wants to close a project because construction is complete, but operations has not accepted the asset. What should the project manager do?', ['Complete or formally resolve the agreed acceptance and transition requirements before closure.','Close immediately because physical completion is the only criterion.','Leave the project open indefinitely without a transition plan.','Assume silence from operations constitutes acceptance.'],'Physical completion and authorized acceptance are distinct. Resolve transition obligations, ownership, and any agreed exceptions through governance rather than either premature closure or unmanaged delay.');
add('R',10,'Hybrid','Which TWO items most directly support sustainable handover of a new service?', ['A named operational owner with support procedures and verified readiness.','A benefits owner and agreed measurement arrangements after transition.','An archive containing source files without access instructions.','A statement that all future questions are outside everyone’s responsibility.','A project closure celebration as the only acceptance evidence.'],'Operational readiness supports continued service, while benefits ownership supports outcome tracking beyond delivery. An archive is useful but does not substitute for accountable operation and measurement.',{type:'multi',answer:[0,1]});
add('R',10,'Predictive','A customer terminates a project early for strategic reasons. What should the project manager do?', ['Perform controlled closure, including contract obligations, records, and disposition of incomplete work.','Skip closure because the planned deliverables will not be completed.','Continue spending until the original scope is finished.','Destroy incomplete work to avoid confusion.'],'Termination still creates responsibilities for funds, assets, suppliers, knowledge, and stakeholders. Controlled closure establishes an accountable end state even when the original objectives are no longer pursued.');
add('R',10,'Agile','A product team will continue after a funded project ends. What should project closure clarify?', ['Ownership of remaining backlog items, funding, support, and benefits responsibilities.','That every backlog idea must be implemented before any project can close.','That closure automatically deletes all product obligations.','That the former project manager remains indefinitely accountable for every future release.'],'A continuing product and a closing project have different boundaries. Agree the transfer of remaining work and responsibilities; an evolving backlog need not be exhausted to close an authorized project scope.');
add('R',10,'Predictive','A supplier’s final invoice includes a disputed variation. What should happen at contract closeout?', ['Resolve or formally manage the dispute according to the agreement and document the remaining obligation.','Pay it automatically to make the project file complete.','Reject every final invoice because one item is disputed.','Delete the variation record after the supplier demobilizes.'],'Closeout must account for outstanding claims and payment obligations. Follow the contract and authorized advice; administrative convenience does not justify automatic payment, blanket rejection, or lost records.');
add('R',10,'Hybrid','A benefits review is scheduled six months after delivery, but the project team disbands next week. What is needed now?', ['Confirm the benefits owner, data access, review date, and escalation route.','Keep every team member assigned until the benefits review.','Report the forecast benefit as already realized.','Cancel measurement because the project has ended.'],'Benefits may mature after delivery. A clear transfer of ownership and measurement arrangements supports accountability without assuming the full delivery team must remain in place.');
add('R',10,'Predictive','A lessons-learned archive exists, but the next project cannot find relevant lessons. What would improve closure knowledge transfer?', ['Curate actionable lessons with context, searchable tags, and an accessible owner or repository.','Add every project email to the archive without indexing.','Store the lessons only on the departing manager’s laptop.','Remove unsuccessful approaches to keep the record positive.'],'Useful knowledge includes conditions, actions, and consequences in a retrievable form. More unstructured material or selective positive reporting can make the next team less able to apply the learning.');
add('R',10,'Predictive','Match the closure evidence to the question it answers.', ['Acceptance record','Operational readiness evidence','Financial and contractual reconciliation','Lessons and knowledge transfer'], 'Closure evidence should demonstrate authorized acceptance, continuing operation, resolved or assigned obligations, and reusable knowledge. No single document automatically proves every aspect is complete.',{type:'match',rows:['Did the authorized customer accept the agreed deliverables?','Can the receiving team support and maintain the result?','Are payments, claims, and remaining liabilities accounted for?','Can future teams retrieve and apply what was learned?'],answer:[0,1,2,3]});
add('R',6,'Predictive','A project has EAC $840,000 and actual cost $315,000. What estimate to complete is implied?', ['$525,000','$1,155,000','$315,000','$840,000'],'ETC = EAC − AC = $525,000. EAC includes both spending to date and forecast remaining cost; adding actual cost again double-counts the work already performed.',{type:'dropdown'});
add('R',8,'Predictive','In the network shown, select the first activity on the critical path. There are no resource constraints.', ['A','B','C','D'],'Path A–C takes 4 + 5 = 9 days; path B–D takes 6 + 5 = 11 days. B is the first activity on the longer controlling path. Activity duration alone is not the definition of criticality.',{type:'hotspot',graphic:'network',answer:[1]});
add('R',7,'Hybrid','The chart shows escaped defects after comparable releases. A new automated check was introduced before release C. What should the team conclude?', ['The reduction is encouraging, but investigate other influences before attributing it entirely to the check.','The chart proves the automated check caused every improvement.','Release D requires no testing because defects fell.','The earlier releases must have used fewer features despite no such data.'],'A before-and-after association supports investigation, not definitive causal attribution. Check comparability, detection changes, and other interventions, then continue monitoring effectiveness.',{graphic:'bars',chart:{title:'Escaped defects after release',unit:'defects',labels:['Release A','Release B','Release C','Release D'],values:[18,20,9,8]}});
add('R',3,'Hybrid','Two features cost the same. One has strong evidence of reducing customer rework; the other is popular internally but has no tested outcome hypothesis. What is the best next step?', ['Use evidence and strategic fit to compare value, testing the uncertain hypothesis if warranted.','Select the internally popular feature because enthusiasm guarantees adoption.','Treat equal cost as proof of equal value.','Reject every uncertain feature without considering a small learning experiment.'],'Value decisions consider benefits, evidence, risk, and strategy as well as cost. A bounded experiment may reduce uncertainty; popularity and equal expenditure alone do not establish comparable outcomes.');
// Business Environment — 58 additional items.
add('B',5,'Hybrid','In the flood-warning case, how should the delayed gauge delivery be managed?', ['Assess exposure during the gap, activate the approved fallback as appropriate, and monitor its effectiveness.','Assume the approved fallback removes all residual risk.','Report that notifications are fast enough to offset missing gauge coverage.','Wait for the gauges before discussing the exposure.'],'The fallback can reduce exposure but must be operational and monitored. App speed does not replace missing observations or demonstrate coverage for vulnerable households.',{case:'river'});
add('B',1,'Hybrid','In the museum case, the sponsor wants the affected crates moved before conservation approval. What should the project manager do?', ['Present the preservation and schedule impacts and obtain a decision through the authorized conservation and governance process.','Treat sponsor urgency as automatic conservation approval.','Ask the carrier to accept responsibility verbally and proceed.','Remove the failed test from the decision package.'],'Decision authority and mandatory acceptance conditions still apply under schedule pressure. Present options and consequences transparently; neither urgency nor a verbal transfer of responsibility establishes approval.',{case:'museum'});
add('B',2,'Hybrid','In the payroll case, the vendor says aggregate reconciliation is enough for go-live. What should govern the decision?', ['The agreed individual-difference disposition criteria and authorized Finance gate.','The vendor’s confidence in aggregate totals.','The small percentage alone, regardless of who is affected.','The project manager’s desire to avoid another rehearsal.'],'Aggregate balance can hide individual errors. Apply the agreed gate and relevant payroll obligations; a small error percentage or vendor assurance does not replace required disposition.',{case:'payroll'});
add('B',5,'Hybrid','In the vaccine case, how should the cheaper route proposal be evaluated?', ['Validate thermal performance and assess service, quality, and cost risks before an authorized change.','Select it based on transport savings alone.','Assume sensor uptime proves the longer route is safe.','Accept the route and investigate only if customers complain.'],'Route cost is one factor in delivering usable shipments. The unvalidated transfer time creates exposure that uptime cannot resolve; gather evidence before making the change.',{case:'coldchain'});
add('B',1,'Agile','In the school case, the sponsor wants to report the target as nearly achieved. What should the project manager make clear?', ['The reported rate excludes abandoned applications and cannot yet establish the intended overall outcome.','The 12% rate proves the 10% target is achieved after rounding.','Families who abandon the process are irrelevant to the benefit.','A favorable headline matters more than measurement consistency.'],'The denominator excludes a relevant group and is not comparable to the intended outcome without clarification. Accountable reporting shows the limitation and obtains a valid measure.',{case:'school'});
add('B',8,'Hybrid','In the battery-facility case, a transport restriction may reduce inbound volume. What is the best response?', ['Assess scenarios for supply, recovery benefits, and business-case viability with the appropriate decision makers.','Continue unchanged because the restriction is outside project control.','Cancel the project immediately without evaluating applicability.','Raise the reported recovery percentage to compensate for lower volume.'],'An external change can affect benefits and viability even when technical delivery remains on plan. Evaluate applicability and alternatives; uncertainty does not justify either inaction or automatic cancellation.',{case:'battery'});
add('B',1,'Predictive','A steering committee delegates minor changes to the project manager but reserves changes above a cost threshold. Several related requests together exceed that threshold. What should happen?', ['Assess the combined impact and follow the applicable governance authority.','Split the requests solely to avoid committee review.','Approve each request without considering the shared purpose.','Assume a supplier may set the approval threshold.'],'Related changes can create a material cumulative commitment. Apply governance to the actual decision and its effects rather than fragmenting work to evade authorized oversight.');
add('B',1,'Hybrid','A bidder offers a team member an expensive personal gift during evaluation. What should the project manager reinforce?', ['Disclose and handle the offer under the organization’s ethics and procurement rules.','Accept it if the bidder does not explicitly ask for a favor.','Keep it private until the contract is awarded.','Award extra points because the gift shows commitment.'],'Even without an explicit exchange, a gift can create an actual or perceived conflict. Transparent handling under applicable policy protects impartial evaluation and trust.');
add('B',1,'Predictive','Which TWO actions support accountable governance at a phase gate?', ['Present material evidence and unresolved exceptions.','Confirm who can authorize continuation and any conditions.','Treat attendance as approval without recording a decision.','Withhold negative findings until funding is released.','Let the team retrospectively invent acceptance criteria.'],'A gate decision requires reliable evidence, clear authority, and traceable conditions. Merely holding a meeting or concealing exceptions does not establish an informed authorization.',{type:'multi',answer:[0,1]});
add('B',1,'Hybrid','A project manager has a financial interest in a proposed subcontractor. What is the appropriate first response?', ['Disclose the conflict and follow the required recusal and review process.','Stay on the panel and promise to be objective without disclosure.','Transfer the shares after award without informing anyone.','Ask the subcontractor to submit through another company name.'],'Disclosure allows the organization to manage the conflict with appropriate safeguards. A personal assurance or concealed arrangement cannot replace transparent handling and independent evaluation.');
add('B',1,'Predictive','A project is on time and budget, but updated evidence shows its expected benefit has disappeared. What should governance consider?', ['Whether to continue, redirect, or stop based on the revised business case.','Whether sunk spending alone justifies finishing every deliverable.','Whether the original approval prohibits reassessment.','Whether reporting only schedule performance avoids the issue.'],'Governance should protect intended value throughout the project. Past expenditure is not recoverable by completing work that no longer has a sound prospective benefit.');
add('B',1,'Hybrid','Match the governance question to the relevant mechanism.', ['Delegated authority','Stage-gate review','Conflict-of-interest management','Benefits oversight'], 'Governance mechanisms clarify who decides, when viability is reviewed, how impartiality is protected, and who monitors outcomes. They should be tailored without losing accountability.',{type:'match',rows:['Who may approve this level of expenditure?','Is there sufficient evidence to proceed to the next phase?','How should a personal interest in a bidder be handled?','Who reviews whether the investment delivers its intended outcome?'],answer:[0,1,2,3]});
add('B',2,'Hybrid','A team wants to upload confidential customer records into a public AI tool to summarize interviews. What should happen first?', ['Verify approved data handling, access, and tool-use requirements and use a compliant method.','Upload the records and delete the browser history afterward.','Assume summarization cannot expose the underlying data.','Let each team member decide independently without checking policy.'],'Data obligations apply to AI inputs as well as outputs. Confirm authorized processing and protections before use; deleting local history does not undo disclosure to a service.');
add('B',2,'Agile','An AI-assisted eligibility tool performs well overall but has a much higher error rate for one user group. What should the team do?', ['Investigate subgroup performance and impacts before accepting the model for its intended use.','Accept it because the overall average exceeds the target.','Remove the subgroup from monitoring to improve the average.','Assume a larger model will automatically remove the disparity.'],'Aggregate accuracy can conceal harmful or unacceptable differences. Assess data, criteria, and consequences with responsible specialists and affected stakeholders rather than hiding the subgroup.');
add('B',2,'Hybrid','Which TWO controls best support responsible use of AI-generated project recommendations?', ['Validate material recommendations against reliable evidence and context.','Keep accountable human decision authority and traceable review.','Treat fluent wording as proof of accuracy.','Allow the tool to approve spending beyond delegated authority.','Avoid recording the basis of decisions made with the tool.'],'AI output may be plausible yet wrong or unsuitable. Evidence-based review and human accountability support defensible decisions; automation does not create authority or eliminate verification.',{type:'multi',answer:[0,1]});
add('B',2,'Predictive','A regulation takes effect before the planned launch. The team believes its existing design may be affected. What is the best next step?', ['Obtain qualified interpretation, assess applicability and impacts, and route required changes appropriately.','Assume the old design is exempt because planning began earlier.','Ask developers to interpret the law without relevant expertise.','Ignore it until a formal enforcement notice arrives.'],'Determine applicable obligations with qualified support, then integrate the resulting work and decisions. Timing assumptions or unqualified guesses cannot establish compliance.');
add('B',2,'Hybrid','A model’s error rate increases after a change in customer behavior. What should ongoing assurance include?', ['Monitor drift, reassess fitness for use, and apply the approved intervention process.','Rely indefinitely on the original validation results.','Hide the new data to preserve the release approval.','Increase automation without investigating the failure.'],'A model can become less suitable when data or operating conditions change. Initial validation is not permanent assurance; monitoring and an intervention route support continued responsible operation.');
add('B',2,'Predictive','Match each compliance concern to the most relevant response.', ['Data minimization and authorized processing','Qualified regulatory interpretation','Traceable human review','Ongoing model monitoring'], 'These responses address different control needs. Compliance and responsible AI require evidence throughout use, not merely an initial approval or confidence in a tool’s output.',{type:'match',rows:['Unnecessary personal fields are included in an analysis export','A new legal requirement may apply to the launch','An AI recommendation would materially affect customer access','Prediction errors rise as operating conditions change'],answer:[0,1,2,3]});
add('B',3,'Predictive','A customer requests a new feature after scope approval. The team estimates it can be built quickly. What should happen before implementation?', ['Assess integrated impacts and obtain the required change decision.','Implement immediately because the coding effort is small.','Reject every request after the baseline is approved.','Exchange it for an unrelated requirement without customer agreement.'],'A small implementation effort can still affect testing, support, cost, or commitments. Change control enables informed decisions; it is neither an automatic refusal nor permission to bypass authority.');
add('B',3,'Agile','A product owner reprioritizes items within delegated scope and funding for the next iteration. What should the project manager recognize?', ['This may be normal adaptive planning within agreed governance.','Every backlog reorder requires a new project charter.','The product owner may also waive all external compliance obligations.','Priorities cannot change after the first iteration.'],'Adaptive delivery allows authorized reprioritization while retaining constraints and accountability. Distinguish routine backlog decisions from changes that exceed scope, funding, or mandatory obligations.');
add('B',3,'Hybrid','Which TWO impacts should be considered when assessing a proposed delivery-date acceleration?', ['Quality, risk, and dependency consequences of compression.','Resource and cost implications for affected teams and operations.','Only the sponsor’s preferred date.','Only the number of calendar days removed.','Whether the dashboard can be made green without changing the plan.'],'An integrated assessment considers feasibility and consequences across delivery and transition. A desired date and visual status do not demonstrate that an accelerated plan is achievable.',{type:'multi',answer:[0,1]});
add('B',3,'Predictive','A change is approved, but the team continues using the previous specification. What is missing?', ['Controlled implementation, communication, and verification of the approved change.','Another request for the same change regardless of the existing decision.','A rule that approvals automatically update every artifact.','Permission for individuals to choose their preferred version.'],'Approval is one step in change management. Update authoritative artifacts, communicate the effective change, and verify execution so the decision becomes the actual delivery basis.');
add('B',3,'Hybrid','An emergency procedure permits temporary action to protect service, with a documented follow-up review. A qualifying outage occurs. What should the project manager do?', ['Use the authorized emergency route and complete its documentation and review requirements.','Wait for a routine monthly meeting despite the emergency authority.','Treat the emergency as permission to bypass all future controls.','Conceal the temporary action to avoid retrospective discussion.'],'Tailored governance can provide timely emergency authority with accountability. Follow the applicable route and its limits; urgency does not remove documentation or subsequent review requirements.');
add('B',3,'Predictive','The chart shows approved changes adding 12, 18, 15, and 25 staff-days across four months. What should the project manager examine?', ['The cumulative 70 staff-days and their effect on capacity and commitments.','Only the latest 25 staff-days because earlier approvals have no continuing impact.','A presumed 25-day project delay without dependency analysis.','Whether each request was small enough to ignore collectively.'],'Cumulative change can materially affect capacity even when each approval is modest. Effort is not automatically elapsed duration; analyze allocation and dependencies before forecasting dates.',{graphic:'bars',chart:{title:'Additional approved effort',unit:'staff-days',labels:['Month 1','Month 2','Month 3','Month 4'],values:[12,18,15,25]}});
add('B',4,'Agile','A team repeatedly waits three days for test access. What should the project manager do first?', ['Understand the access bottleneck with the responsible owner and work to remove it.','Ask the team to increase estimates so the delay is hidden.','Escalate every individual tester as underperforming.','Start more work to keep everyone busy while the queue grows.'],'A recurring systemic impediment needs diagnosis and ownership. Increasing work in progress or concealing the wait does not improve flow and can make the queue worse.');
add('B',4,'Hybrid','An issue exceeds the project manager’s authority and threatens a committed milestone. What should escalation include?', ['Impact, options, a recommendation, and the decision needed by a specified date.','Only a statement that someone else must solve it.','A guarantee of no impact before alternatives are evaluated.','Every historical email without a clear request.'],'Useful escalation equips the authorized decision maker to act. Explain consequences, viable choices, and timing rather than transferring an undefined problem or providing unsupported reassurance.');
add('B',4,'Predictive','Which TWO actions help manage an issue after assigning an owner?', ['Agree the action, due date, and escalation threshold.','Track whether the response resolves the underlying impact.','Close the issue immediately because someone is named.','Remove it from reports until the due date regardless of worsening impact.','Assume assignment grants any required spending authority.'],'Ownership starts accountability but does not prove resolution. Define action and follow-up, and escalate changes in exposure within authority rather than treating assignment as completion.',{type:'multi',answer:[0,1]});
add('B',4,'Hybrid','A supplier outage predicted in the risk register has now occurred. What should the project manager do?', ['Activate the applicable response, manage the issue, and reassess remaining risks.','Keep it only as an uncertain future event.','Delete the risk record and lose its response history.','Wait for the next risk workshop before taking any action.'],'Occurrence turns the uncertain event into a current issue requiring response. Preserve useful links to the risk record and reassess residual or secondary risks as the response proceeds.');
add('B',4,'Agile','Two teams disagree about who owns a blocked interface, and the item has no resolution date. What is the best next step?', ['Facilitate agreement on accountable ownership, required collaboration, and a resolution plan.','Assign blame based on which team reported the issue.','Leave ownership shared without specifying actions.','Have both teams independently build incompatible fixes.'],'Cross-team work still needs explicit accountability and coordinated action. Clarify responsibilities and a plan rather than letting ambiguous shared ownership prolong the blockage.');
add('B',4,'Hybrid','Match the situation to the appropriate response.', ['Resolve within delegated authority','Escalate for a decision','Activate the contingency response','Verify before closure'], 'Issue handling depends on authority, agreed response plans, and evidence of resolution. Escalation is useful when a decision is needed, while closure requires more than an unverified statement.',{type:'match',rows:['A known workaround is approved and within the team’s authority','A required funding decision exceeds the project manager’s limit','A monitored supplier-failure trigger has occurred','The owner reports a fix but the acceptance check is outstanding'],answer:[0,1,2,3]});
add('B',5,'Predictive','A risk has low probability but could cause an unacceptable safety consequence. What should determine its treatment?', ['Risk appetite, consequence, and applicable requirements as well as probability.','Probability alone because low likelihood always means low priority.','Whether the risk fits within the status report’s page limit.','Whether the team has previously experienced the event.'],'A low likelihood does not automatically make severe consequences acceptable. Apply the organization’s criteria and relevant requirements; absence of past occurrence is not proof of tolerable exposure.');
add('B',5,'Hybrid','The team buys insurance for a specified financial exposure. What should it recognize?', ['Some financial consequences may transfer, while residual obligations and risks remain.','The uncertain event can no longer occur.','All schedule, reputation, and operational consequences are eliminated.','No further monitoring is needed once the premium is paid.'],'Risk transfer changes allocation of covered consequences, not the possibility of the event or every resulting obligation. Understand exclusions and residual exposure and continue appropriate monitoring.');
add('B',5,'Predictive','Which TWO details make a contingency plan actionable?', ['A clear activation trigger and accountable owner.','Resources and authority needed to execute the response.','Only a generic instruction to be careful.','A promise that the event will not occur.','A decision to wait until all possible impacts are certain.'],'An actionable response specifies when, who, and how, including resources and authority. Vague caution and certainty requirements delay action when the planned trigger is reached.',{type:'multi',answer:[0,1]});
add('B',5,'Hybrid','A response reduces one risk but introduces another dependency on a single specialist. How should this be handled?', ['Assess and manage the secondary risk created by the response.','Assume all consequences of an approved response are acceptable.','Remove the new dependency from risk reporting.','Cancel every response that introduces any new uncertainty.'],'Responses can create secondary risks that need assessment and ownership. Approval is not evidence that new exposure is negligible; evaluate the net effect and practical treatment options.');
add('B',5,'Predictive','An opportunity could shorten commissioning if an early training pilot succeeds. What should the team do?', ['Assess the opportunity and assign a proportionate response and owner.','Exclude it because risk management concerns only threats.','Book the full time saving before the pilot provides evidence.','Spend unlimited funds because the outcome is favorable.'],'Uncertainty includes opportunities as well as threats. Evaluate likelihood, benefit, cost, and a response; a possible gain should not be treated as already realized.');
add('B',5,'Predictive','Using the displayed matrix, select the cell for HIGH probability and MEDIUM impact.', ['Low probability / low impact','Low probability / medium impact','Low probability / high impact','Medium probability / low impact','Medium probability / medium impact','Medium probability / high impact','High probability / low impact','High probability / medium impact','High probability / high impact'],'High probability is the top row and medium impact is the middle column, giving an illustrative score of 3 × 2 = 6. The score supports prioritization under this matrix, not a universal risk acceptance rule.',{type:'hotspot',graphic:'risk',answer:[7]});
add('B',6,'Agile','A retrospective produces the same action for three iterations, but nobody implements it. What should change?', ['Choose a feasible improvement with an owner, completion point, and a check of its effect.','Add more actions without considering capacity.','Stop retrospectives because the team already knows the problem.','Record the repeated action as completed to improve morale.'],'Learning needs an implemented and evaluated change. A small accountable experiment is more useful than accumulating unowned intentions or treating discussion as improvement.');
add('B',6,'Hybrid','A pilot process improves speed but increases downstream rework. What should the team evaluate?', ['The end-to-end outcome and trade-offs before scaling the process.','Only the local speed metric.','Whether rework can be assigned to another department’s budget.','Whether the pilot team prefers the new process.'],'Local optimization can worsen overall performance. Evaluate flow, quality, and outcomes across the full system; moving costs between teams does not remove them.');
add('B',6,'Agile','Which TWO practices make an improvement experiment more informative?', ['Define the hypothesis and meaningful success measures in advance.','Compare results with a suitable baseline while checking other influences.','Change every process at once and attribute all results to one action.','Keep only observations that support the proposed improvement.','Declare success based solely on team enthusiasm.'],'A clear hypothesis and a credible comparison support learning. Consider other changes and unfavorable data; enthusiasm and selective observations cannot establish effectiveness.',{type:'multi',answer:[0,1]});
add('B',6,'Predictive','A project discovers a useful inspection method midway through delivery. When should the learning be shared?', ['When validated and relevant, with context, rather than waiting only for closure.','Only after every project document is archived.','Only if the method was in the original plan.','Only with the individual who first suggested it.'],'Timely knowledge sharing can improve current and parallel work. Explain the conditions and evidence so others can judge applicability; closure is not the only opportunity to learn.');
add('B',6,'Hybrid','A team copies another project’s process improvement, but performance deteriorates. What should it examine?', ['Differences in context and assumptions and whether the method should be adapted or stopped.','Whether the other project’s success guarantees eventual success here.','Whether the team can hide the adverse results until acceptance.','Whether all process improvements should now be prohibited.'],'Practices depend on context. Use evidence to tailor or reverse an ineffective change rather than assuming transferability or generalizing one failed adoption to every improvement.');
add('B',6,'Agile','The chart shows average queue time before and after a trial change. Which next step best supports continuous improvement?', ['Confirm comparability, examine the change’s effects, and decide whether to retain or adapt it.','Assume the final value guarantees the same result forever.','Stop measuring because queue time decreased.','Claim that customer satisfaction doubled without measuring it.'],'The queue time reduction is evidence worth investigating. Verify comparable conditions and related outcomes, then continue monitoring; a process measure alone does not establish a specific customer benefit.',{graphic:'bars',chart:{title:'Average queue time',unit:'hours',labels:['Baseline 1','Baseline 2','Trial 1','Trial 2'],values:[24,26,16,14]}});
add('B',7,'Hybrid','A new tool is delivered successfully, but employees continue using spreadsheets. What should the project manager and change owner investigate?', ['Adoption barriers, workflow fit, incentives, and support needs.','Only whether installation completed on time.','Whether removing all spreadsheets immediately will prove the benefit.','Whether delivery automatically transfers responsibility for every adoption issue to users.'],'Technical availability does not establish adoption. Understand why people retain the old workflow and coordinate suitable support and organizational changes before assuming resistance or forcing a solution.');
add('B',7,'Predictive','A restructuring changes who will own the delivered service. What should be revalidated?', ['Transition responsibilities, readiness, and stakeholder commitments.','Only the project logo on status reports.','Nothing, because the old owner signed the original charter.','Only whether the outgoing owner still attends meetings.'],'Organizational changes can invalidate ownership and readiness assumptions. Confirm the receiving organization’s ability and commitment to operate the outcome, rather than relying on obsolete assignments.');
add('B',7,'Hybrid','Which TWO indicators provide stronger evidence of change adoption than training attendance alone?', ['Observed use of the new workflow in real tasks.','Users’ ability to perform required activities with appropriate support.','The number of invitation emails sent.','The length of the training slide deck.','The fact that the sponsor approved the communications plan.'],'Attendance and communications are activities. Actual use and demonstrated capability provide more direct evidence of adoption, although outcome measures are still needed to assess benefits.',{type:'multi',answer:[0,1]});
add('B',7,'Agile','Front-line staff oppose a new process because it adds steps during peak demand. What is the best first response?', ['Observe the work with them and assess the concern against the intended outcome.','Label them resistant and repeat the announcement.','Promise to remove every control before understanding its purpose.','Ask managers to prohibit all feedback.'],'Resistance may reveal a genuine workflow or capacity problem. Understand the evidence and purpose of the steps before choosing changes, support, or communication.');
add('B',7,'Hybrid','A change champion leaves just before rollout. What should the project manager coordinate?', ['A replacement or shared support arrangement and transfer of local knowledge and responsibilities.','Assume formal training eliminates the need for local support.','Delay all work indefinitely until the same person returns.','Keep the departure out of readiness reporting.'],'Change support depends on capabilities and relationships, not simply a name in a plan. Assess the gap and arrange a practical transition with the organizational change owner.');
add('B',7,'Predictive','Match the adoption need to a suitable response.', ['Explain purpose and expected impact','Develop task capability','Remove workflow barriers','Reinforce and monitor adoption'], 'Awareness, capability, opportunity, and reinforcement address different reasons a change may not take hold. Tailor the intervention to evidence rather than repeating the same communication for every problem.',{type:'match',rows:['Users do not understand why the process is changing','Users understand the purpose but cannot perform the new task','Users are trained but lack necessary system access','Initial use falls after rollout and old habits return'],answer:[0,1,2,3]});
add('B',8,'Predictive','A currency movement materially increases the forecast cost of imported equipment. What should the project manager do?', ['Assess contractual exposure and update forecasts and response options with finance and procurement.','Keep the old exchange rate because it was used in the baseline.','Assume the supplier automatically absorbs every exchange movement.','Change the approved budget without authorization.'],'External financial conditions can affect exposure depending on contract terms and hedging arrangements. Update the evidence and seek the appropriate decision; a baseline is not a current forecast.');
add('B',8,'Hybrid','A competitor launches a service that changes customer expectations during development. What is the best response?', ['Reassess the value proposition and options with the product and business owners.','Copy every competitor feature immediately.','Ignore the launch because the backlog was already approved.','Cancel the project solely because competition exists.'],'Market changes merit evidence-based reassessment. Determine their effect on customers and strategy before changing scope or investment; neither copying nor automatic cancellation is justified by the event alone.');
add('B',8,'Predictive','Which TWO practices help detect external changes early?', ['Assign owners to monitor relevant regulatory, market, and supply signals.','Review the assumptions supporting the business case at appropriate intervals.','Assume external conditions remain fixed after authorization.','Limit scanning to risks that have already occurred.','Exclude operational stakeholders from all horizon reviews.'],'Assigned monitoring and periodic assumption review connect external signals to project decisions. Waiting for realized impacts or treating initial assumptions as permanent reduces response time.',{type:'multi',answer:[0,1]});
add('B',8,'Hybrid','A new sustainability target affects energy consumption after handover. What should be evaluated?', ['Lifecycle performance, design options, and impacts on the business case and acceptance basis.','Only construction energy because operations occurs after the project.','Only whether the target was known at kickoff.','A favorable sustainability claim without supporting measurement.'],'Sustainability objectives can affect operational outcomes and investment decisions. Assess relevant lifecycle impacts and authorized changes rather than restricting attention to the delivery period.');
add('B',8,'Predictive','A regional disruption may affect two suppliers that were assumed to be independent backups. What should the risk review examine?', ['Their shared exposure and whether the contingency still provides resilience.','Only each supplier’s contractual delivery date.','Whether two company names guarantee independent supply.','Whether the disruption can be excluded because it is external.'],'Backup effectiveness depends on independence of the relevant failure modes. A shared region, facility, or transport route can create correlated exposure even with separate contracts.');
add('B',8,'Hybrid','A government incentive central to the business case is withdrawn before commissioning. What should the sponsor receive?', ['A revised viability assessment with options and implications for a decision.','Only the original approved benefit figure.','A statement that technical progress makes the incentive irrelevant.','A guarantee that another incentive will replace it.'],'A material external assumption has changed. Reassess prospective value and options transparently; technical completion and unsupported replacement assumptions do not restore the missing benefit.');
add('B',5,'Predictive','A risk has a 25% probability of a $160,000 cost impact. What is its expected monetary value for this simplified calculation?', ['$40,000','$160,000','$120,000','$640,000'],'EMV = probability × impact = 0.25 × $160,000 = $40,000. This is a probability-weighted value, not a guaranteed loss or automatically sufficient reserve for a single severe event.',{type:'dropdown'});
add('B',2,'Hybrid','An AI-generated summary cites a regulation the reviewer cannot locate. What should happen before the recommendation is used?', ['Verify the claim against an authoritative source and correct or reject unsupported content.','Accept the citation because it appears professionally formatted.','Ask the same tool to repeat the answer and treat repetition as verification.','Remove the citation but retain the unsupported legal conclusion.'],'Generated citations can be inaccurate or fabricated. Independent verification is needed for material claims; confident formatting, repetition, or removing attribution does not establish validity.');
add('B',5,'Hybrid','Select the matrix cell for LOW probability and HIGH impact.', ['Low probability / low impact','Low probability / medium impact','Low probability / high impact','Medium probability / low impact','Medium probability / medium impact','Medium probability / high impact','High probability / low impact','High probability / medium impact','High probability / high impact'],'Low probability is the bottom row; high impact is the rightmost column. Its illustrative score is 1 × 3 = 3. Equal numeric scores can hide different consequence profiles and should be interpreted with context.',{type:'hotspot',graphic:'risk',answer:[2]});
add('B',6,'Hybrid','A team wants to scale an improvement after one successful trial involving only expert users. What should it do next?', ['Test applicability with representative users and operating conditions before broader rollout.','Assume expert performance represents every user group.','Remove the need for training because experts succeeded.','Guarantee the same benefit across every business unit.'],'The trial provides useful but limited evidence. Representative conditions help reveal training, usability, and operating differences before a broader commitment; one selected group cannot establish universal effectiveness.');
})();
